MODULES = [
(u"模組 A｜微生物的世界", [

lesson(u"看不見的世界", u"從雷文霍克到巴斯德",
  [u"了解微生物的發現", u"理解自然發生說的終結", u"認識微生物的種類與大小"],
  [("h", u"一位布商的鏡片"),
   ("p", u"1670 年代，荷蘭台夫特的布商<strong>雷文霍克</strong>用自己磨製的小透鏡（放大倍率約兩三百倍）觀察雨水、池水、牙垢，看到了無數游動的「<strong>微小動物</strong>」。他從 1673 年起寫了數百封信給英國皇家學會，詳細描述了細菌、原生生物與精子。他沒有受過正規的科學訓練，卻成為「微生物學之父」。在他之前，虎克在 1665 年的《顯微圖譜》中描繪了軟木的「細胞」與黴菌。"),
   ("h", u"自然發生說的終結"),
   ("p", u"微生物從哪裡來？許多人相信它們會從腐敗的物質中「自然發生」。1859～1862 年，法國的<strong>巴斯德</strong>做了著名的<strong>鵝頸瓶實驗</strong>：把肉湯煮沸後放在彎曲細長頸的瓶子中，空氣可以進入，但灰塵與微生物被困在彎曲處。肉湯可以保持清澈好幾年；一旦把瓶頸打斷，很快就長滿了微生物。結論：<strong>微生物來自微生物</strong>。（部分巴斯德的原始瓶子至今仍保存在巴黎的巴斯德研究所，肉湯依然清澈。）"),
   ("h", u"巴斯德的遺產"),
   ("ul", [u"<strong>發酵是微生物造成的</strong>：酒變酸是因為雜菌污染（見" + X("fermentation", u"發酵") + u"）。", u"<strong>巴斯德殺菌法</strong>：溫和加熱殺死有害的微生物，同時保留風味——最早用於葡萄酒，後來用於牛奶（" + LS(16) + u"）。", u"<strong>疫苗</strong>：1885 年成功用減毒的狂犬病疫苗救活了被瘋狗咬傷的男孩（" + LS(14) + u"）。"]),
   ("h", u"微生物的家族"),
   ("t", [u"類群", u"大小（約略）", u"例子"], [[u"細菌", u"0.5～5 微米", u"大腸桿菌、乳酸菌（" + LS(2) + u"）"], [u"古菌", u"0.5～5 微米", u"甲烷菌、嗜鹽菌（" + LS(3) + u"）"], [u"真菌", u"酵母約 5 微米；黴菌的菌絲可以很長", u"酵母、青黴菌、香菇（" + LS(4) + u"）"], [u"原生生物與藻類", u"數微米到數百微米", u"草履蟲、瘧原蟲、矽藻（" + LS(5) + u"）"], [u"病毒", u"20～300 奈米", u"流感病毒、噬菌體（" + LS(6) + u"）"]]),
   ("p", u"1 微米是千分之一公釐：一根頭髮的直徑約可並排 50～100 個大腸桿菌。病毒還要再小十到一百倍，必須用電子顯微鏡才看得到。"),
   ("h", u"微生物的地球"),
   ("p", u"微生物在地球上已經存在超過 35 億年，比動植物早了約 30 億年。它們無所不在：深海熱泉、南極冰層、地下數公里的岩石、雲中、你的皮膚與腸道裡。地球上細菌細胞的總數估計約 10<sup>30</sup> 個。它們製造了大氣中的氧氣、驅動了碳與氮的循環（" + LS(23) + u"）——沒有微生物，就沒有我們。只有極少數的微生物會致病。"),
  ],
  u"1670 年代台夫特布商雷文霍克以自磨約兩三百倍透鏡觀察雨水池水牙垢看到微小動物，1673 年起寫數百封信給皇家學會，被稱微生物學之父，之前虎克 1665 年顯微圖譜描繪軟木細胞與黴菌；1859～1862 年巴斯德鵝頸瓶實驗煮沸肉湯空氣可入但微生物困在彎曲處保持清澈，打斷瓶頸則長滿，微生物來自微生物，部分原始瓶子保存在巴斯德研究所仍清澈；巴斯德證明發酵是微生物造成、發明巴斯德殺菌法、1885 年減毒狂犬病疫苗救活男孩；細菌與古菌 0.5～5 微米、真菌酵母約 5 微米、原生生物藻類數微米到數百微米、病毒 20～300 奈米，頭髮直徑可並排 50～100 個大腸桿菌；微生物存在超過 35 億年早動植物約 30 億年，無所不在，地球細菌約 10^30 個，製造氧氣驅動碳氮循環，只有極少數致病。",
  [u"巴斯德的鵝頸瓶實驗是如何否定自然發生說的？", u"比較細菌與病毒的大小。", u"為什麼說「沒有微生物，就沒有我們」？"]),

lesson(u"細菌的構造", u"簡單卻精巧的細胞",
  [u"認識細菌細胞的構造", u"理解革蘭氏染色", u"理解抗生素的選擇性毒性"],
  [("h", u"原核細胞"),
   ("p", u"細菌是<strong>原核生物</strong>：沒有細胞核，DNA 直接位於細胞質中；也沒有粒線體、內質網等有膜的胞器。它們雖然簡單，卻是演化上極為成功的生命形式。"),
   CELL,
   ("h", u"形狀"),
   ("ul", [u"<strong>球菌</strong>：圓形，例如鏈球菌（成串）、葡萄球菌（成簇）。", u"<strong>桿菌</strong>：棒狀，例如大腸桿菌、枯草桿菌。", u"<strong>螺旋菌</strong>：彎曲或螺旋狀，例如幽門螺旋桿菌（胃潰瘍，" + LS(15) + u"）、梅毒螺旋體。"]),
   ("h", u"革蘭氏染色"),
   ("p", u"1884 年，丹麥醫師<strong>革蘭</strong>發明了一種染色方法：先用結晶紫染色、碘液固定，再用酒精脫色，最後用番紅複染。<strong>革蘭氏陽性菌</strong>的細胞壁有厚的肽聚醣層，保留紫色；<strong>革蘭氏陰性菌</strong>的肽聚醣層薄，外面還有一層外膜，紫色被洗掉而呈紅色。一百多年後，它仍然是臨床微生物學最基本的第一步：醫師常常根據革蘭氏染色的結果，在培養結果出來之前先選擇抗生素。"),
   ("h", u"選擇性毒性"),
   ("p", u"理想的抗生素要「殺死細菌、不傷人體」——這叫做<strong>選擇性毒性</strong>。關鍵在於找出細菌有、人體沒有（或很不一樣）的構造：細胞壁（人體細胞沒有）、70S 核糖體（人體是 80S）、細菌特有的代謝途徑（例如葉酸的合成：細菌自己合成葉酸，人體從食物中攝取——磺胺類藥物就是阻斷細菌合成葉酸）。這是 20 世紀初<strong>埃爾利希</strong>提出的「<strong>魔法子彈</strong>」理想（" + LS(17) + u"）。"),
   ("h", u"內孢子"),
   ("p", u"某些細菌（例如芽孢桿菌、梭菌）在環境惡劣時會形成<strong>內孢子</strong>：把 DNA 包在多層堅固的外殼中，進入休眠。內孢子能耐受煮沸、乾燥、輻射與許多消毒劑，存活數十年甚至更久。肉毒桿菌、破傷風梭菌、炭疽桿菌都能形成孢子——這正是滅菌必須使用高壓蒸氣的原因（" + LS(16) + u"）。"),
  ],
  u"細菌為原核生物無細胞核 DNA 位於細胞質，無粒線體內質網等有膜胞器；形狀有球菌（鏈球菌成串葡萄球菌成簇）、桿菌（大腸桿菌枯草桿菌）、螺旋菌（幽門螺旋桿菌梅毒螺旋體）；1884 年革蘭發明染色：結晶紫、碘液固定、酒精脫色、番紅複染，陽性菌肽聚醣厚保留紫色，陰性菌薄且有外膜呈紅色，至今仍是臨床第一步可在培養前選抗生素；選擇性毒性找細菌有人體沒有的構造：細胞壁、70S 核糖體、葉酸合成（磺胺類阻斷），即埃爾利希魔法子彈理想；芽孢桿菌梭菌形成內孢子包 DNA 於多層外殼休眠，耐煮沸乾燥輻射消毒劑存活數十年，肉毒桿菌破傷風炭疽皆能形成，故滅菌需高壓蒸氣。",
  [u"細菌細胞和人體細胞最大的不同是什麼？", u"說明革蘭氏染色的步驟與原理。", u"什麼是選擇性毒性？舉一個例子。"]),

lesson(u"古菌與生命之樹", u"第三種生命",
  [u"了解古菌的發現", u"理解三域系統", u"認識極端環境微生物"],
  [("h", u"用分子重畫生命之樹"),
   ("p", u"傳統上，生物被分成動物、植物等「界」，而所有的原核生物都被歸為「細菌」。1977 年，美國伊利諾大學的<strong>沃斯</strong>想到：所有生物都有核糖體，核糖體 RNA（<strong>16S rRNA</strong>）的序列變化緩慢，可以當作測量演化關係的「分子時鐘」。比較各種微生物的 16S rRNA 後，他驚訝地發現：一群產甲烷的微生物，和一般的細菌差異之大，不亞於細菌和人類的差異。"),
   ("h", u"三域系統"),
   ("p", u"沃斯提出把生命分成三個<strong>域</strong>：<strong>細菌</strong>、<strong>古菌</strong>與<strong>真核生物</strong>（包括動物、植物、真菌、原生生物）。古菌外表像細菌（沒有細胞核、大小相似），但它們的細胞膜脂質、DNA 複製與基因表現的機制，反而更接近真核生物。這個想法一開始遭到強烈的質疑，後來被大量的基因體證據支持，徹底改變了我們對生命演化的理解（見" + X("genetics-dna", u"遺傳與 DNA") + u"）。近年的研究更指出，真核生物可能就是從古菌的一支（阿斯嘉古菌）演化而來。"),
   ("h", u"極端環境的居民"),
   ("t", [u"類型", u"喜歡的環境", u"例子"], [[u"嗜熱菌", u"80 °C 以上，最高紀錄約 122 °C", u"深海熱泉、溫泉"], [u"嗜鹽菌", u"飽和鹽水", u"死海、曬鹽場（呈現粉紅色）"], [u"嗜酸菌", u"pH 0～2", u"酸性礦坑排水"], [u"嗜冷菌", u"0 °C 附近", u"極地冰層、深海"], [u"甲烷菌", u"無氧", u"沼澤、牛的瘤胃、稻田、人的腸道"]]),
   ("p", u"不過，古菌並不只住在極端環境：海洋、土壤、人體中也都有大量的古菌。至今還沒有發現會讓人生病的古菌。"),
   ("h", u"極端微生物的禮物"),
   ("ul", [u"<strong>Taq 聚合酶</strong>：從美國黃石公園溫泉的嗜熱細菌中分離，耐高溫，讓 PCR 成為可能（" + LS(12) + u"）。", u"<strong>甲烷</strong>：甲烷菌產生的甲烷，是沼氣與天然氣的來源之一，也是強效的溫室氣體——牛打嗝排出的甲烷來自瘤胃中的甲烷菌（見" + X("climate-change", u"氣候變遷") + u"）。", u"<strong>天文生物學</strong>：極端微生物讓科學家思考，生命可能存在於火星的地下或木衛二的冰下海洋。"]),
  ],
  u"傳統所有原核生物歸為細菌，1977 年伊利諾大學沃斯以變化緩慢的 16S rRNA 為分子時鐘比較微生物，發現產甲烷微生物與一般細菌差異不亞於細菌和人類；提出細菌、古菌、真核生物三域，古菌外表像細菌但膜脂質 DNA 複製基因表現更接近真核，起初遭質疑後被基因體證據支持，近年指出真核生物可能從阿斯嘉古菌演化；嗜熱菌 80 °C 以上最高約 122 °C 深海熱泉、嗜鹽菌飽和鹽水死海曬鹽場呈粉紅、嗜酸菌 pH 0～2 酸性礦坑、嗜冷菌極地深海、甲烷菌無氧沼澤瘤胃稻田腸道，古菌也大量存在海洋土壤人體，尚未發現致病古菌；Taq 聚合酶從黃石溫泉嗜熱細菌分離使 PCR 可能、甲烷菌產沼氣也是溫室氣體牛打嗝、天文生物學思考火星與木衛二生命。",
  [u"沃斯是用什麼方法發現古菌的？", u"古菌和細菌有什麼相同與不同？", u"舉兩個極端微生物對人類的貢獻。"]),

lesson(u"真菌：酵母與黴菌", u"分解者與好幫手",
  [u"認識真菌的構造與分類", u"了解真菌在食品與醫藥中的角色", u"了解真菌引起的疾病與毒素"],
  [("h", u"比較接近動物"),
   ("p", u"真菌是<strong>真核生物</strong>，有細胞核與粒線體。它們曾經被歸為植物，但不行光合作用，細胞壁的成分是<strong>幾丁質</strong>（和昆蟲的外殼相同）而非纖維素。分子證據顯示：真菌和<strong>動物</strong>的親緣關係，比和植物更接近。這也是為什麼抗真菌藥物比抗生素難開發——真菌細胞和我們的細胞太像了。"),
   ("h", u"三種形態"),
   ("ul", [u"<strong>酵母</strong>：單細胞，以出芽方式繁殖。釀酒酵母是麵包、啤酒、葡萄酒的主角（見" + X("fermentation", u"發酵") + u"），也是研究真核細胞最重要的模式生物之一。", u"<strong>黴菌</strong>：由細長的<strong>菌絲</strong>組成，交織成菌絲體，產生大量的孢子隨空氣散播。麵包上的毛狀黴斑，就是菌絲與孢子。", u"<strong>蕈類</strong>：我們吃的香菇、金針菇，是真菌的「子實體」（產生孢子的構造），地下還有龐大的菌絲網。美國奧勒岡州的一株蜜環菌，菌絲網覆蓋約 9 平方公里，被認為是世界上最大的生物之一。"]),
   ("h", u"自然界的分解者"),
   ("p", u"真菌分泌消化酵素到環境中，再吸收分解後的養分。它們是森林中最重要的<strong>分解者</strong>，特別是能分解木材中堅硬的木質素——沒有真菌，倒下的樹木會堆積如山。約九成的陸地植物，根部和真菌形成<strong>菌根</strong>共生：真菌幫植物吸收水分與磷，植物供給真菌糖分（" + LS(23) + u"）。"),
   ("h", u"真菌與人類"),
   ("t", [u"用途", u"真菌"], [[u"麵包、酒、醬油、味噌、豆腐乳", u"酵母、麴菌（米麴菌）"], [u"起司", u"洛克福羊乳酪的藍綠色紋路來自青黴菌"], [u"抗生素", u"盤尼西林（青黴菌，" + LS(17) + u"）"], [u"免疫抑制劑", u"環孢素（器官移植的關鍵藥物）"], [u"降膽固醇藥", u"最早的他汀類藥物來自真菌"], [u"檸檬酸", u"黑麴菌大量發酵生產（" + LS(24) + u"）"]]),
   ("h", u"真菌的危害"),
   ("ul", [u"<strong>真菌毒素</strong>：<strong>黃麴毒素</strong>由麴菌產生在發霉的花生、玉米中，是極強的肝癌致癌物，而且<strong>煮沸也無法破壞</strong>——發霉的花生不能只挑掉壞的那一顆（見" + X("analytical-chemistry", u"分析化學") + u"的食品檢驗）。中世紀歐洲的「聖安東尼之火」，則是麥角菌污染黑麥造成的中毒。", u"<strong>感染</strong>：香港腳、灰指甲、念珠菌感染。免疫力低下的病人（愛滋病、化療、器官移植）可能發生致命的侵襲性黴菌感染。近年出現的<strong>耳念珠菌</strong>對多種抗真菌藥物具抗藥性，在醫院中造成群聚感染，引起全球關注。", u"<strong>農業</strong>：稻熱病、香蕉的黃葉病；1840 年代的愛爾蘭大饑荒由馬鈴薯晚疫病引起（病原其實是卵菌，過去被歸為真菌）。"]),
  ],
  u"真菌為真核生物有細胞核粒線體，曾歸植物但不行光合作用，細胞壁為幾丁質非纖維素，分子證據顯示與動物較近，故抗真菌藥難開發；酵母單細胞出芽繁殖為麵包啤酒葡萄酒主角及模式生物，黴菌由菌絲組成產大量孢子，蕈類為子實體，奧勒岡蜜環菌菌絲網約 9 平方公里為最大生物之一；真菌分泌酵素分解吸收是森林最重要分解者能分解木質素，約九成陸地植物與真菌形成菌根共生；用途有麵包酒醬油味噌豆腐乳、洛克福藍紋起司青黴菌、盤尼西林、環孢素器官移植、他汀類、黑麴菌檸檬酸；危害有黃麴毒素肝癌致癌物煮沸無法破壞發霉花生不能只挑壞的、中世紀聖安東尼之火麥角中毒、香港腳灰指甲念珠菌、免疫低下侵襲性黴菌感染、耳念珠菌多重抗藥醫院群聚、稻熱病香蕉黃葉病、1840 年代愛爾蘭大饑荒馬鈴薯晚疫病（卵菌）。",
  [u"為什麼說真菌和動物比較接近？", u"為什麼發霉的花生不能只挑掉壞的那一顆？", u"列舉三種真菌對人類有益的用途。"]),

lesson(u"原生生物與藻類", u"單細胞的多樣世界",
  [u"認識原生生物的多樣性", u"了解藻類對地球的重要性", u"了解瘧疾等原生生物疾病"],
  [("h", u"「其他」的真核生物"),
   ("p", u"<strong>原生生物</strong>是一個方便但不嚴謹的類別：不屬於動物、植物、真菌的真核生物，大多是單細胞。它們的多樣性極高，演化上彼此的差異可能比動物和植物之間還大。"),
   ("h", u"類似動物的原生動物"),
   ("ul", [u"<strong>草履蟲</strong>：靠全身的纖毛游動，是高中生物實驗的常客。", u"<strong>變形蟲</strong>：伸出偽足移動與吞食。少數種類可以致病，例如溫水中的福氏內格里阿米巴會經由鼻腔侵入腦部，極為罕見但幾乎致命（俗稱「食腦變形蟲」）。", u"<strong>鞭毛蟲</strong>：例如造成昏睡病的錐蟲（以采采蠅傳播）、在白蟻腸道中幫忙分解木頭的共生鞭毛蟲。"]),
   ("h", u"瘧疾"),
   ("p", u"<strong>瘧疾</strong>是人類歷史上最致命的疾病之一，由<strong>瘧原蟲</strong>引起，經由瘧蚊叮咬傳播。瘧原蟲在人體的肝臟與紅血球中繁殖，造成週期性的高燒。今天全世界每年仍有約兩億多個病例、約 60 萬人死亡，大多是非洲的幼兒。"),
   ("ul", [u"<strong>奎寧</strong>：來自南美金雞納樹的樹皮，17 世紀起用於治療瘧疾（見" + X("organic-chemistry", u"有機化學") + u"的生物鹼）。", u"<strong>青蒿素</strong>：中國的屠呦呦從中醫古籍得到靈感，從青蒿中萃取出抗瘧的有效成分，獲得 2015 年諾貝爾醫學獎（見" + X("chinese-medicine", u"中醫") + u"、" + X("nobel-medicine", u"諾貝爾醫學獎") + u"）。", u"<strong>台灣</strong>：日治與戰後初期瘧疾盛行，經過大規模的噴灑 DDT 與病例追蹤，台灣在 1965 年獲世界衛生組織認證<strong>根除瘧疾</strong>。", u"<strong>疫苗</strong>：2021 年起世界衛生組織推薦第一支瘧疾疫苗用於非洲兒童——寄生蟲的疫苗比病毒與細菌難開發得多。"]),
   ("h", u"藻類：地球的肺"),
   ("p", u"<strong>藻類</strong>是能行光合作用的原生生物（加上藍綠菌這種細菌）。海洋中的<strong>浮游植物</strong>——矽藻、甲藻、藍綠菌——雖然肉眼看不見，卻貢獻了地球上相當大比例（常被估計約一半）的光合作用與氧氣生產，也是海洋食物鏈的基礎。<strong>矽藻</strong>有精美的玻璃質（二氧化矽）外殼，死後沉積成矽藻土，用於過濾與研磨。"),
   ("h", u"藻華與赤潮"),
   ("p", u"當水中的氮、磷過多（農業肥料、生活污水），藻類大量繁殖，形成<strong>藻華</strong>。某些甲藻與藍綠菌會產生毒素：貝類吃了有毒的藻類，人再吃貝類，就可能發生<strong>麻痺性貝毒</strong>中毒；藻類死亡分解時消耗大量的溶氧，造成魚群死亡（見" + X("analytical-chemistry", u"分析化學") + u"的溶氧、" + X("water-environment", u"水資源與環境") + u"）。"),
  ],
  u"原生生物為不屬動植物真菌的真核生物多為單細胞，多樣性極高；草履蟲纖毛游動、變形蟲偽足移動，福氏內格里阿米巴經鼻腔侵入腦極罕見但幾乎致命、鞭毛蟲如錐蟲昏睡病采采蠅傳播與白蟻腸道共生鞭毛蟲；瘧疾由瘧原蟲經瘧蚊傳播在肝臟紅血球繁殖週期性高燒，每年約兩億多病例約 60 萬死亡多為非洲幼兒，奎寧來自金雞納樹 17 世紀起使用、屠呦呦青蒿素 2015 年諾貝爾醫學獎、台灣噴灑 DDT 病例追蹤 1965 年 WHO 認證根除瘧疾、2021 年起 WHO 推薦首支瘧疾疫苗；藻類行光合作用，海洋浮游植物矽藻甲藻藍綠菌貢獻約一半光合作用與氧氣為海洋食物鏈基礎，矽藻玻璃質外殼沉積成矽藻土；氮磷過多形成藻華，甲藻藍綠菌毒素經貝類造成麻痺性貝毒，藻類死亡分解耗溶氧魚群死亡。",
  [u"瘧疾是如何傳播的？台灣如何根除瘧疾？", u"為什麼說海洋中的浮游植物對地球很重要？", u"藻華是如何形成的？會造成什麼危害？"]),

lesson(u"病毒", u"生命的邊界",
  [u"理解病毒的構造與複製", u"了解病毒是否是生物的爭論", u"認識噬菌體與病毒的重要性"],
  [("h", u"比細菌更小的病原"),
   ("p", u"1892 年，俄國的<strong>伊萬諾夫斯基</strong>發現：引起菸草嵌紋病的病原，能穿過可以擋住所有細菌的瓷濾器。1898 年，荷蘭的<strong>拜耶林克</strong>重複實驗，認為這是一種「有傳染性的活液體」，稱之為<strong>病毒</strong>（拉丁文的「毒液」）。直到 1930 年代電子顯微鏡發明，人類才第一次看見病毒。"),
   ("h", u"病毒的構造"),
   ("ul", [u"<strong>基因體</strong>：DNA 或 RNA（只有一種），單股或雙股。", u"<strong>蛋白質外殼</strong>（衣殼）：保護基因體，常呈二十面體或螺旋狀。", u"<strong>套膜</strong>（部分病毒才有）：從宿主細胞膜「借來」的脂質膜，上面插著病毒的蛋白質（例如流感病毒的血球凝集素、新冠病毒的棘蛋白）。有套膜的病毒怕肥皂與酒精——所以洗手對它們特別有效（" + LS(16) + u"）。"]),
   ("h", u"複製：劫持細胞"),
   ("p", u"病毒沒有自己的代謝系統與核糖體，必須進入宿主細胞，利用細胞的機器複製自己："),
   ("ol", [u"<strong>吸附</strong>：病毒表面的蛋白質和細胞上的特定受體結合（決定了病毒感染哪些物種、哪些組織）。", u"<strong>進入</strong>與<strong>脫殼</strong>。", u"<strong>合成</strong>：利用細胞的核糖體製造病毒蛋白，複製病毒基因體。", u"<strong>組裝</strong>。", u"<strong>釋出</strong>：讓細胞破裂，或從細胞膜「出芽」。一個被感染的細胞可以釋出成千上萬個新病毒。"]),
   ("h", u"病毒是生物嗎？"),
   ("p", u"病毒有遺傳物質、會演化，卻不能獨立代謝與繁殖。它們處在生物與非生物的<strong>邊界</strong>上。2003 年發現的<strong>擬菌病毒</strong>（mimivirus）比某些細菌還大、基因比某些細菌還多，讓這個爭論更加有趣。"),
   ("h", u"噬菌體"),
   ("p", u"專門感染細菌的病毒叫做<strong>噬菌體</strong>（1915 年特沃特、1917 年德埃雷爾分別發現）。它們是地球上數量最多的生物實體（估計約 10<sup>31</sup> 個），每天殺死海洋中相當比例的細菌，深刻影響全球的物質循環。噬菌體也是分子生物學的功臣：證明 DNA 是遺傳物質的赫希－蔡斯實驗（1952）就是用噬菌體做的。在抗藥性細菌日益嚴重的今天，用噬菌體治療細菌感染的<strong>噬菌體療法</strong>重新受到重視（" + LS(18) + u"）。"),
   ("h", u"病毒與我們"),
   ("p", u"人類基因體中約 8% 是古代反轉錄病毒留下的序列；其中一些甚至被「馴化」成有用的基因，例如胎盤形成所需的合胞素。病毒也被改造成工具：基因治療的載體、mRNA 疫苗之外的病毒載體疫苗、溶瘤病毒療法（" + LS(19) + u"）。"),
  ],
  u"1892 年伊萬諾夫斯基發現菸草嵌紋病病原能穿過擋住細菌的瓷濾器，1898 年拜耶林克稱有傳染性的活液體病毒，1930 年代電子顯微鏡才看見；病毒有 DNA 或 RNA 基因體、蛋白質衣殼二十面體或螺旋、部分有從宿主借來的套膜插病毒蛋白如血球凝集素棘蛋白，套膜病毒怕肥皂酒精；病毒無代謝與核糖體需劫持細胞：吸附特定受體決定宿主組織、進入脫殼、合成、組裝、破裂或出芽釋出成千上萬新病毒；病毒有遺傳物質會演化卻不能獨立代謝繁殖處於生物邊界，2003 年擬菌病毒比某些細菌大；噬菌體 1915 年特沃特 1917 年德埃雷爾發現，約 10^31 個為最多的生物實體，赫希－蔡斯 1952 年以噬菌體證明 DNA 為遺傳物質，噬菌體療法重受重視；人類基因體約 8% 為古代反轉錄病毒序列，合胞素用於胎盤形成，病毒也改造為基因治療載體病毒載體疫苗溶瘤病毒。",
  [u"病毒的基本構造有哪些？", u"為什麼有套膜的病毒特別怕肥皂？", u"你認為病毒是生物嗎？說明你的理由。"]),
]),

(u"模組 B｜生長與代謝", [

lesson(u"細菌的生長", u"指數的威力",
  [u"理解二分裂與倍增時間", u"讀懂細菌的生長曲線", u"了解影響生長的環境因素"],
  [("h", u"一變二、二變四"),
   ("p", u"細菌以<strong>二分裂</strong>繁殖：一個細胞長大、複製 DNA，再分裂成兩個相同的細胞。在理想的條件下，大腸桿菌每 <strong>20 分鐘</strong>就能分裂一次。一個細菌經過 n 代，就變成 2<sup>n</sup> 個——10 代約一千個、20 代約一百萬個、30 代約十億個。只要 10 小時，一個大腸桿菌理論上就能變成十億個（見" + X("differential-equations", u"微分方程") + u"的指數成長）。"),
   ("p", u"當然，指數成長不可能永遠持續：養分會耗盡、廢物會累積。如果一個細菌真的以 20 分鐘倍增持續兩天，後代的總質量將超過地球。"),
   GROWTH,
   ("h", u"四個階段"),
   ("ol", [u"<strong>遲滯期</strong>：細菌剛到新環境，忙著合成需要的酵素，數量幾乎不增加。", u"<strong>對數期</strong>（指數期）：以固定的倍增時間生長。這時的細菌最活躍，對抗生素也最敏感（許多抗生素作用於正在生長的細胞）。", u"<strong>穩定期</strong>：養分耗盡、廢物累積，新生與死亡大致平衡。許多細菌在這個階段才產生抗生素或毒素等「二級代謝物」。", u"<strong>死亡期</strong>：死亡多於新生，數量呈指數下降。"]),
   ("h", u"影響生長的因素"),
   ("t", [u"因素", u"說明"], [[u"溫度", u"多數致病菌最適合 30～40 °C（人的體溫）。低溫減慢、高溫殺死（" + LS(16) + u"）"], [u"pH", u"多數細菌喜歡中性；醃漬、發酵食品的酸性能抑制雜菌（" + LS(21) + u"）"], [u"水活性", u"可利用的水分。糖漬、鹽漬、乾燥讓細菌「缺水」"], [u"氧氣", u"好氧菌需要氧；厭氧菌（例如肉毒桿菌）怕氧；兼性厭氧菌（例如大腸桿菌）兩者皆可"], [u"養分", u"碳源、氮源、維生素、微量元素"]]),
   ("h", u"食物的危險溫度帶"),
   ("p", u"食品衛生中常說的<strong>危險溫度帶</strong>約為 <strong>7～60 °C</strong>：在這個範圍內，細菌能快速繁殖。所以熟食應該保持在 60 °C 以上或冷藏在 7 °C 以下，在室溫下不宜放置超過約兩小時。便當、辦桌菜在夏天放太久，正是許多食物中毒的原因（" + LS(22) + u"）。"),
  ],
  u"細菌以二分裂繁殖，大腸桿菌理想條件每 20 分鐘分裂一次，n 代變 2^n 個，10 代約千、20 代約百萬、30 代約十億，10 小時一個變十億個，若持續兩天總質量超過地球；四階段為遲滯期合成酵素數量幾乎不變、對數期固定倍增最活躍對抗生素最敏感、穩定期養分耗盡生死平衡產二級代謝物、死亡期指數下降；影響因素有溫度多數致病菌 30～40 °C、pH 中性醃漬發酵酸性抑菌、水活性糖漬鹽漬乾燥、氧氣好氧厭氧兼性厭氧、養分；危險溫度帶約 7～60 °C，熟食保持 60 °C 以上或冷藏 7 °C 以下，室溫不宜超過約兩小時，夏天便當辦桌菜放太久是食物中毒原因。",
  [u"一個每 20 分鐘分裂一次的細菌，6 小時後會變成多少個？", u"說明細菌生長曲線的四個階段。", u"為什麼熟食不能在室溫下放太久？"]),

lesson(u"培養與無菌技術", u"柯霍的實驗室革命",
  [u"了解純培養的意義與方法", u"認識培養基與洋菜的故事", u"理解無菌操作的原則"],
  [("h", u"純培養"),
   ("p", u"要研究一種細菌，首先要把它和其他微生物分開，得到只有一種細菌的<strong>純培養</strong>。在液體中，各種細菌混在一起，很難分開。德國醫師<strong>柯霍</strong>的關鍵想法是：在<strong>固體</strong>表面上，一個細菌會在原地繁殖成一團肉眼看得見的<strong>菌落</strong>——每一個菌落都來自一個細胞，就是一個純的族群。他一開始用馬鈴薯切片，後來改用加了明膠的培養液。"),
   ("h", u"洋菜的故事"),
   ("p", u"明膠有兩個問題：在 37 °C（培養致病菌的溫度）會融化，而且很多細菌能分解它。1881 年，柯霍實驗室的研究員<strong>赫塞</strong>的妻子<strong>芬妮．赫塞</strong>提出建議：用她做果醬與果凍的<strong>洋菜</strong>（從紅藻中萃取，源自亞洲的食材）。洋菜在約 85 °C 以上才會融化、約 40 °C 以下凝固，而且幾乎沒有細菌能分解它——完美的材料，至今仍是微生物實驗室的標準。1887 年，柯霍的助手<strong>佩特里</strong>發明了有蓋的淺盤——<strong>培養皿</strong>（Petri dish）。"),
   ("h", u"劃線分離"),
   ("p", u"用接種環沾取樣品，在洋菜平板上以「之」字形分區劃線：每一區都把前一區的細菌稀釋，到最後一區，細菌分散到彼此分開，長出獨立的單一菌落。再從單一菌落挑出細菌，就得到純培養。這個方法一百多年來幾乎沒有改變。"),
   ("h", u"培養基"),
   ("ul", [u"<strong>一般培養基</strong>：提供多數細菌生長所需的養分。", u"<strong>選擇性培養基</strong>：加入抑制某些微生物的成分，只讓目標微生物生長。", u"<strong>鑑別培養基</strong>：讓不同的細菌呈現不同的顏色或反應，例如血液瓊脂上，某些鏈球菌會溶解紅血球而在菌落周圍出現透明環。"]),
   ("h", u"無菌技術"),
   ("ul", [u"工作前後消毒桌面；在酒精燈火焰附近或<strong>生物安全櫃</strong>中操作。", u"接種環在火焰中燒到通紅、冷卻後再使用。", u"打開試管或培養皿的時間越短越好，蓋子不要朝上放。", u"所有的培養物與廢棄物，在丟棄前都要經過高壓滅菌（" + LS(16) + u"）。"]),
   ("h", u"看不見的大多數"),
   ("p", u"一個令人謙卑的事實：自然環境中的微生物，可能有<strong>99% 以上</strong>無法用現有的方法在實驗室中培養——它們需要特殊的條件或其他微生物的「合作」。今天，科學家用<strong>宏基因體學</strong>直接定序環境樣品中所有的 DNA，不必培養就能知道「誰在那裡」（" + LS(20) + u"）。"),
  ],
  u"研究細菌需先得純培養，液體中難分開，柯霍關鍵想法為固體表面一個細菌原地繁殖成菌落每菌落來自一細胞，先用馬鈴薯切片後用明膠；明膠 37 °C 會融化且易被分解，1881 年柯霍實驗室赫塞之妻芬妮．赫塞建議用做果醬果凍的洋菜（紅藻萃取源自亞洲），約 85 °C 以上融化 40 °C 以下凝固幾乎不被分解至今為標準，1887 年佩特里發明培養皿；劃線分離以接種環之字形分區稀釋得單一菌落；培養基有一般、選擇性（抑制某些微生物）、鑑別性（如血液瓊脂溶血透明環）；無菌技術消毒桌面在火焰旁或生物安全櫃操作、接種環燒紅冷卻、開蓋時間短蓋子不朝上、廢棄物高壓滅菌；環境中可能 99% 以上微生物無法培養，以宏基因體學直接定序。",
  [u"為什麼柯霍要用固體培養基？", u"洋菜比明膠好在哪裡？", u"如何用劃線法得到純培養？"]),

lesson(u"微生物的代謝多樣性", u"吃石頭、呼吸鐵",
  [u"理解微生物取得能量與碳的方式", u"了解發酵與呼吸", u"認識微生物對地球化學的影響"],
  [("h", u"能量與碳"),
   ("p", u"所有的生物都需要<strong>能量</strong>與<strong>碳</strong>。動物從有機物（食物）取得兩者；植物用陽光取得能量、用 CO₂ 取得碳。微生物的選擇則多得驚人："),
   ("t", [u"類型", u"能量來源", u"碳來源", u"例子"], [[u"光自營", u"光", u"CO₂", u"藍綠菌、藻類"], [u"化學自營", u"無機物（H₂S、NH₃、Fe²⁺、H₂）", u"CO₂", u"硝化菌、硫細菌、深海熱泉的微生物"], [u"化學異營", u"有機物", u"有機物", u"大多數的細菌、所有的真菌與動物"], [u"光異營", u"光", u"有機物", u"某些紫色非硫細菌"]]),
   ("p", u"19 世紀末，俄國微生物學家<strong>維諾格拉德斯基</strong>發現了<strong>化學自營</strong>：某些細菌能靠氧化無機物（例如硫化氫、氨）取得能量，完全不需要陽光或有機物——等於「吃石頭」維生。深海熱泉周圍整個生態系，都建立在這種微生物之上。"),
   ("h", u"呼吸與發酵"),
   ("ul", [u"<strong>有氧呼吸</strong>：把有機物完全氧化成 CO₂ 與水，以氧氣接受電子，產生最多的能量（見" + X("cell-energy", u"細胞能量") + u"）。", u"<strong>無氧呼吸</strong>：用氧以外的物質接受電子：硝酸鹽、硫酸鹽、甚至<strong>鐵</strong>與<strong>錳</strong>的氧化物。有些細菌能把電子「傳」到細胞外的金屬或電極上——微生物燃料電池就是利用這種能力發電。", u"<strong>發酵</strong>：沒有外部的電子接受者，只把有機物部分分解，產生乳酸、酒精、CO₂ 等，能量較少。這正是優格、酒、麵包、泡菜的化學基礎（" + LS(21) + u"）。"]),
   ("h", u"改變地球的微生物"),
   ("p", u"約 24 億年前，<strong>藍綠菌</strong>的產氧光合作用讓大氣中的氧氣大量增加——<strong>大氧化事件</strong>。這對當時的厭氧生物是一場災難，卻為後來需要氧氣的複雜生命鋪路。今天我們呼吸的每一口氧氣，最初都來自微生物。植物細胞中的<strong>葉綠體</strong>，正是遠古被吞入的藍綠菌演化而來（內共生理論，" + LS(2) + u"）。"),
   ("h", u"固氮"),
   ("p", u"空氣中 78% 是氮氣，但 N≡N 三鍵極強，大多數生物無法利用。只有某些細菌與古菌擁有<strong>固氮酶</strong>，能在常溫常壓下把 N₂ 轉成氨——工業上的哈伯法卻需要數百度高溫與數百大氣壓（見" + X("chemical-engineering", u"化學工程") + u"）。豆科植物的根瘤中住著<strong>根瘤菌</strong>，所以豆類不太需要氮肥，傳統農業會輪作豆科植物來「養地」（" + LS(23) + u"）。"),
  ],
  u"生物需能量與碳，光自營以光與 CO2 如藍綠菌藻類、化學自營以無機物 H2S NH3 Fe2+ H2 與 CO2 如硝化菌硫細菌熱泉微生物、化學異營以有機物如多數細菌真菌動物、光異營以光與有機物如紫色非硫細菌；19 世紀末維諾格拉德斯基發現化學自營細菌氧化無機物取得能量即吃石頭，深海熱泉生態系建立於此；有氧呼吸完全氧化產能最多，無氧呼吸以硝酸鹽硫酸鹽鐵錳氧化物接受電子，有些細菌把電子傳到胞外金屬電極即微生物燃料電池，發酵無外部電子接受者部分分解產乳酸酒精 CO2 為優格酒麵包泡菜基礎；約 24 億年前藍綠菌產氧光合作用造成大氧化事件，氧氣最初來自微生物，葉綠體由被吞入的藍綠菌演化；固氮酶常溫常壓把 N2 轉成氨而哈伯法需高溫高壓，豆科根瘤菌使豆類少需氮肥輪作養地。",
  [u"什麼是化學自營？舉一個例子。", u"有氧呼吸、無氧呼吸與發酵有什麼不同？", u"為什麼豆科植物比較不需要氮肥？"]),
]),

(u"模組 C｜遺傳與生物技術", [

lesson(u"細菌的遺傳與基因轉移", u"橫向交換基因",
  [u"理解突變與細菌的快速演化", u"認識轉形、接合與轉導", u"了解基因水平轉移的重要性"],
  [("h", u"快速演化的機器"),
   ("p", u"細菌的突變率不高（每個鹼基每次複製約十億分之一），但它們的族群極大、世代極短。一毫升的培養液中有十億個細菌，每一代都會產生大量的突變株——只要環境中出現篩選壓力（例如抗生素），帶有有利突變的極少數就會脫穎而出（" + LS(18) + u"）。美國的<strong>倫斯基</strong>從 1988 年起，連續培養同一批大腸桿菌超過七萬代，親眼看到演化的發生：其中一支族群演化出了利用檸檬酸的新能力。"),
   ("h", u"基因的水平轉移"),
   ("p", u"動物只能從親代得到基因（垂直轉移）。細菌卻還能從<strong>其他細菌</strong>——甚至不同種的細菌——直接取得基因，叫做<strong>基因水平轉移</strong>。有三種主要的方式："),
   ("ul", [u"<strong>轉形</strong>：從環境中吸收裸露的 DNA 片段。1928 年，英國的<strong>格里菲斯</strong>發現：把加熱殺死的有莢膜（致病）肺炎鏈球菌和活的無莢膜（無害）菌混在一起注入小鼠，小鼠竟然死了，而且分離出活的有莢膜菌——某種「轉形因子」把無害菌變成了致病菌。1944 年，<strong>艾佛瑞</strong>等人證明這個轉形因子就是 <strong>DNA</strong>，這是 DNA 為遺傳物質的第一個有力證據（見" + X("genetics-dna", u"遺傳與 DNA") + u"）。", u"<strong>接合</strong>：兩個細菌透過性線毛接觸，把質體 DNA 從一個傳給另一個——類似細菌的「交配」。1946 年由<strong>萊德伯格</strong>與<strong>塔特姆</strong>發現（1958 年諾貝爾獎）。", u"<strong>轉導</strong>：噬菌體在組裝時，不小心把宿主的 DNA 片段包進去，再注入下一個細菌（" + LS(6) + u"）。"]),
   ("h", u"為什麼重要"),
   ("p", u"基因水平轉移讓有用的基因能在細菌世界中快速傳播："),
   ("ul", [u"<strong>抗藥性</strong>：抗藥性基因常位於質體上，可以在不同種的細菌之間傳遞——一種在動物腸道中產生的抗藥性，可能轉移到人類的病原菌（" + LS(18) + u"）。", u"<strong>毒力</strong>：霍亂弧菌的毒素基因來自一種噬菌體；腸道出血性大腸桿菌（如 O157:H7）的志賀毒素基因也來自噬菌體（" + LS(15) + u"）。", u"<strong>新的代謝能力</strong>：分解新的污染物、適應新的環境。"]),
   ("p", u"基因水平轉移也讓「生命之樹」（" + LS(3) + u"）的根部更像一張糾纏的「網」。"),
  ],
  u"細菌突變率約每鹼基每次複製十億分之一，但族群極大世代極短，一毫升十億細菌每代大量突變株，篩選壓力下有利突變脫穎而出，倫斯基 1988 年起連續培養大腸桿菌超過七萬代看到一支演化出利用檸檬酸能力；基因水平轉移從其他甚至不同種細菌取得基因：轉形吸收裸露 DNA，1928 年格里菲斯加熱殺死的有莢膜菌與活無莢膜菌混合使小鼠死亡，1944 年艾佛瑞證明轉形因子為 DNA；接合透過性線毛傳質體 1946 年萊德伯格與塔特姆發現 1958 年諾貝爾獎；轉導由噬菌體誤包宿主 DNA 注入下一細菌；重要性在抗藥性質體跨種傳遞、毒力如霍亂毒素與 O157:H7 志賀毒素基因來自噬菌體、新代謝能力，使生命之樹根部像糾纏的網。",
  [u"為什麼細菌能夠快速演化？", u"說明格里菲斯實驗的過程與意義。", u"轉形、接合、轉導有什麼不同？"]),

lesson(u"CRISPR：細菌的免疫系統", u"從鹽田到諾貝爾獎",
  [u"了解 CRISPR 在細菌中的原始功能", u"理解 CRISPR-Cas9 基因編輯的原理", u"認識 CRISPR 的應用與倫理"],
  [("h", u"奇怪的重複序列"),
   ("p", u"1987 年，日本大阪大學的<strong>石野良純</strong>在大腸桿菌的基因附近，發現了一段奇怪的重複序列，但當時不知道它的功能。1990 年代起，西班牙阿利坎特大學的<strong>莫希卡</strong>研究鹽田中的嗜鹽古菌，在許多微生物中都發現了類似的結構：一段段相同的短重複序列，中間夾著各不相同的「間隔序列」。他後來為它取了名字：<strong>CRISPR</strong>（成簇規律間隔短回文重複）。"),
   ("h", u"細菌記得病毒"),
   ("p", u"2005 年前後，莫希卡等人發現：那些間隔序列和<strong>噬菌體</strong>的 DNA 一模一樣！CRISPR 是細菌的<strong>適應性免疫系統</strong>：細菌被病毒感染而倖存時，會把病毒 DNA 的一小段剪下來，存進自己的 CRISPR 陣列中，像是一本「通緝犯相簿」。下次同一種病毒入侵，細菌把這段記憶轉錄成 RNA，引導 <strong>Cas</strong> 蛋白（一種核酸酶）找到並切斷病毒的 DNA。2007 年，丹麥優格公司 Danisco 的科學家用製作優格的嗜熱鏈球菌證實了這個機制——他們想讓菌種能抵抗噬菌體，以免整批優格發酵失敗（" + LS(21) + u"）。"),
   ("h", u"從細菌免疫到基因剪刀"),
   ("p", u"2012 年，<strong>道納</strong>與<strong>夏彭蒂耶</strong>證明：Cas9 蛋白只需要一段<strong>引導 RNA</strong>，就能在試管中精準地切斷任何指定的 DNA 序列——只要改變引導 RNA 的 20 個鹼基，就能把「剪刀」導向任何基因。很快，其他團隊（包括張鋒等人）在人類細胞中成功運用。CRISPR-Cas9 比以前的基因編輯技術簡單、便宜、快速得多，迅速席捲全世界的實驗室。道納與夏彭蒂耶獲得 2020 年諾貝爾化學獎（見" + X("nobel-chemistry", u"諾貝爾化學獎") + u"）。"),
   ("h", u"應用"),
   ("ul", [u"<strong>醫學</strong>：2023 年，第一個 CRISPR 基因編輯療法（治療鐮刀型貧血症與乙型地中海型貧血）獲得英國與美國核准。", u"<strong>農業</strong>：抗病、耐旱的作物，不褐變的蘑菇。", u"<strong>診斷</strong>：利用 Cas 蛋白辨識特定的序列，開發快速的病毒檢測。", u"<strong>基礎研究</strong>：快速剔除基因，研究它的功能。"]),
   ("h", u"倫理的界線"),
   ("p", u"2018 年，中國科學家<strong>賀建奎</strong>宣布用 CRISPR 編輯了人類胚胎，誕生了一對雙胞胎女嬰，聲稱讓她們能抵抗愛滋病毒。這引起了全球科學界的強烈譴責：安全性未知、沒有醫療必要、知情同意有嚴重瑕疵，而且編輯會遺傳給後代。他後來被判刑入獄。這個事件凸顯了<strong>生殖細胞基因編輯</strong>的倫理爭議（見" + X("human-experiments", u"人體實驗與研究倫理") + u"）。"),
   ("p", u"一個來自鹽田與優格的基礎研究，變成了改變醫學的技術——這是好奇心驅動的基礎科學最好的例子之一。"),
  ],
  u"1987 年大阪大學石野良純在大腸桿菌發現奇怪重複序列，1990 年代起西班牙阿利坎特大學莫希卡研究鹽田嗜鹽古菌發現短重複序列夾間隔序列，命名 CRISPR；2005 年前後發現間隔序列與噬菌體 DNA 相同，CRISPR 是細菌適應性免疫系統，倖存時剪下病毒 DNA 存入陣列如通緝犯相簿，再轉錄成 RNA 引導 Cas 核酸酶切斷病毒，2007 年丹麥 Danisco 以優格嗜熱鏈球菌證實；2012 年道納與夏彭蒂耶證明 Cas9 只需引導 RNA 改 20 個鹼基即可切任何指定 DNA，張鋒等在人類細胞運用，2020 年諾貝爾化學獎；2023 年首個 CRISPR 療法治鐮刀型貧血與乙型地中海型貧血在英美核准，農業抗病耐旱作物不褐變蘑菇，快速病毒診斷，基因剔除研究；2018 年賀建奎編輯人類胚胎誕生雙胞胎遭全球譴責後判刑入獄，凸顯生殖細胞編輯倫理爭議；來自鹽田與優格的基礎研究改變醫學。",
  [u"CRISPR 在細菌中原本的功能是什麼？", u"CRISPR-Cas9 如何找到並切斷特定的 DNA？", u"為什麼賀建奎的實驗受到強烈的譴責？"]),

lesson(u"微生物與生物技術", u"細菌工廠",
  [u"了解重組 DNA 技術與基因工程菌", u"理解 PCR 與 Taq 聚合酶", u"認識微生物在醫藥生產中的角色"],
  [("h", u"重組 DNA"),
   ("p", u"1973 年，<strong>柯恩</strong>與<strong>博耶</strong>把一段外來的 DNA 剪接到細菌的<strong>質體</strong>上，放回大腸桿菌中，結果細菌複製質體時，也一起複製了這段外來的 DNA。這是<strong>重組 DNA 技術</strong>的誕生：細菌成了能大量複製任何基因、生產任何蛋白質的「工廠」。工具來自細菌自己——<strong>限制酶</strong>（細菌用來切斷入侵病毒 DNA 的「剪刀」）與 DNA 連接酶。"),
   ("h", u"人類胰島素"),
   ("p", u"過去，糖尿病患者使用的胰島素從屠宰場的豬與牛的胰臟中萃取，供應有限，少數人會過敏。1978 年，博耶共同創辦的<strong>基因泰克</strong>公司把人類胰島素的基因放進大腸桿菌，讓細菌生產<strong>人類胰島素</strong>；1982 年上市，是第一個基因工程藥物。今天，胰島素、生長激素、凝血因子、許多疫苗與抗體藥物，都由基因工程的細菌、酵母或哺乳動物細胞生產（見" + X("pharmacology", u"藥理學") + u"）。"),
   ("h", u"PCR 與溫泉細菌"),
   ("p", u"1983 年，<strong>穆利斯</strong>在開車途中想到了<strong>聚合酶連鎖反應</strong>（PCR）：反覆加熱（分開雙股 DNA）與冷卻（讓引子結合、聚合酶複製），每一個循環讓目標 DNA 加倍，30 個循環就能放大約十億倍。問題是：一般的 DNA 聚合酶在加熱時就壞了，每個循環都要重新加。"),
   ("p", u"解答來自<strong>黃石公園</strong>的溫泉。1969 年，微生物學家<strong>布羅克</strong>從溫泉中分離出嗜熱的<strong>水生棲熱菌</strong>（Thermus aquaticus）。它的 DNA 聚合酶——<strong>Taq 聚合酶</strong>——能耐受接近沸騰的溫度。用了 Taq，PCR 就能全自動地進行。穆利斯獲得 1993 年諾貝爾化學獎。PCR 改變了生物學、醫學診斷與法醫學（見" + X("analytical-chemistry", u"分析化學") + u"的 DNA 鑑定）；新冠肺炎疫情中，PCR 檢測成了家喻戶曉的名詞。一個看似「無用」的溫泉細菌研究，帶來了價值數十億美元的產業。"),
   ("h", u"其他生物技術"),
   ("ul", [u"<strong>酵素</strong>：洗衣粉中的蛋白酶與脂肪酶來自細菌；乳糖酶讓乳糖不耐症的人能喝牛奶。", u"<strong>疫苗</strong>：B 型肝炎疫苗是由基因工程酵母生產的表面抗原——台灣自 1984 年起全面為新生兒接種，大幅降低了肝癌的發生率（見" + X("immunology-vaccines", u"免疫學與疫苗") + u"）。", u"<strong>生物農藥</strong>：蘇力菌（Bt）產生的蛋白質只對特定昆蟲的幼蟲有毒，被廣泛用於有機農業。", u"<strong>合成生物學</strong>：重新設計微生物的代謝途徑，生產藥物（例如青蒿素的前驅物）、香料、生質燃料（" + LS(24) + u"）。"]),
  ],
  u"1973 年柯恩與博耶把外來 DNA 剪接到質體放回大腸桿菌一起複製，重組 DNA 誕生，細菌成為工廠，工具限制酶（細菌切病毒 DNA 的剪刀）與連接酶來自細菌；過去胰島素從豬牛胰臟萃取供應有限少數過敏，1978 年基因泰克把人類胰島素基因放入大腸桿菌，1982 年上市為首個基因工程藥物，今日胰島素生長激素凝血因子疫苗抗體皆由工程細菌酵母細胞生產；1983 年穆利斯想到 PCR 反覆加熱冷卻每循環加倍 30 循環約十億倍，但一般聚合酶加熱即壞，1969 年布羅克從黃石溫泉分離水生棲熱菌其 Taq 聚合酶耐近沸騰溫度使 PCR 自動化，1993 年諾貝爾化學獎，改變生物醫學診斷法醫；洗衣粉蛋白酶脂肪酶、乳糖酶、B 型肝炎疫苗由工程酵母生產台灣 1984 年起全面接種降低肝癌、蘇力菌 Bt 生物農藥、合成生物學生產青蒿素前驅物。",
  [u"什麼是重組 DNA 技術？它的工具從哪裡來？", u"為什麼 Taq 聚合酶對 PCR 如此重要？", u"台灣全面接種 B 型肝炎疫苗帶來了什麼成果？"]),
]),

(u"模組 D｜微生物與疾病", [

lesson(u"病原論與柯霍法則", u"證明細菌會致病",
  [u"了解病原論的建立", u"理解柯霍法則及其限制", u"認識流行病學的開端"],
  [("h", u"瘴氣與洗手"),
   ("p", u"19 世紀中葉以前，許多人相信疾病是由「<strong>瘴氣</strong>」（腐敗物散發的壞空氣）引起的。1847 年，維也納總醫院的<strong>塞麥爾維斯</strong>注意到：由醫師接生的病房，產婦死於<strong>產褥熱</strong>的比例遠高於由助產士接生的病房。他推論：醫師從解剖室直接到產房，手上帶著「屍體顆粒」。他要求醫師用漂白水洗手，產褥熱的死亡率大幅下降。但他的主張在當時遭到排斥，最後他在精神病院中去世。今天他被稱為「母親們的救星」。"),
   ("h", u"約翰．斯諾與霍亂"),
   ("p", u"1854 年倫敦蘇活區爆發霍亂。醫師<strong>斯諾</strong>把死亡病例標在地圖上，發現它們集中在寬街的一個公共水泵周圍。他說服當局拆掉水泵的把手，疫情隨之平息。這張「霍亂地圖」被視為<strong>流行病學</strong>的開端——當時還沒有人知道霍亂是細菌引起的。"),
   ("h", u"柯霍的證明"),
   ("p", u"德國醫師<strong>柯霍</strong>以嚴謹的實驗證明了特定的細菌造成特定的疾病：1876 年<strong>炭疽桿菌</strong>，1882 年 3 月 24 日宣布發現<strong>結核桿菌</strong>（這一天後來成為世界結核病日），1883 年霍亂弧菌。他獲得 1905 年諾貝爾醫學獎（見" + X("nobel-medicine", u"諾貝爾醫學獎") + u"）。"),
   ("h", u"柯霍法則"),
   ("ol", [u"在所有患病的個體中都能找到這種微生物，健康的個體中則沒有。", u"能從患病的個體中分離出這種微生物，得到純培養（" + LS(8) + u"）。", u"把純培養接種到健康的個體，會引起同樣的疾病。", u"能從實驗感染的個體中再次分離出同樣的微生物。"]),
   ("h", u"法則的限制"),
   ("ul", [u"<strong>健康帶原者</strong>：例如「傷寒瑪麗」，本身沒有症狀卻傳染了數十人。", u"<strong>無法培養</strong>：例如造成痲瘋病的痲瘋桿菌至今仍無法在人工培養基中生長；病毒必須在細胞中培養（" + LS(6) + u"）。", u"<strong>倫理</strong>：不能故意讓人感染致命的疾病。", u"<strong>多重病因</strong>：許多疾病是多種微生物、宿主與環境共同作用的結果。"]),
   ("p", u"一個著名的例外：1980 年代，澳洲的<strong>馬歇爾</strong>與<strong>華倫</strong>主張胃潰瘍是由<strong>幽門螺旋桿菌</strong>引起的，但當時的醫學界認為胃酸中不可能有細菌存活。為了證明，馬歇爾<strong>自己喝下</strong>了一杯細菌培養液，幾天後就出現了胃炎。兩人獲得 2005 年諾貝爾醫學獎。今天，用抗生素根除幽門螺旋桿菌能治癒大多數的胃潰瘍，並降低胃癌的風險（" + LS(15) + u"）。"),
  ],
  u"19 世紀中葉前多信瘴氣致病，1847 年維也納總醫院塞麥爾維斯發現醫師接生病房產褥熱死亡率遠高於助產士病房，推論醫師從解剖室帶屍體顆粒，要求漂白水洗手死亡率大降但遭排斥死於精神病院，被稱母親們的救星；1854 年倫敦蘇活區霍亂斯諾把病例標在地圖集中於寬街水泵，拆掉把手疫情平息為流行病學開端；柯霍 1876 年炭疽桿菌、1882 年 3 月 24 日結核桿菌（世界結核病日）、1883 年霍亂弧菌，1905 年諾貝爾醫學獎；柯霍法則：患病個體皆有健康者無、可分離得純培養、接種健康個體引起同病、可再分離；限制有健康帶原者如傷寒瑪麗、無法培養如痲瘋桿菌與病毒、倫理、多重病因；1980 年代馬歇爾與華倫主張幽門螺旋桿菌致胃潰瘍，馬歇爾自己喝下培養液出現胃炎，2005 年諾貝爾醫學獎，根除可治癒胃潰瘍降低胃癌風險。",
  [u"塞麥爾維斯是如何發現洗手能降低產褥熱的？", u"說明柯霍法則的四個步驟。", u"馬歇爾如何證明幽門螺旋桿菌會引起胃炎？"]),

lesson(u"人體的防禦與疫苗", u"對抗微生物的兩道防線",
  [u"了解先天免疫與適應性免疫", u"理解疫苗的原理與歷史", u"了解疫苗消滅疾病的成就"],
  [("h", u"第一道防線"),
   ("p", u"人體每天都暴露在大量的微生物中，但很少生病。<strong>物理與化學屏障</strong>擋住了大多數的入侵者：完整的皮膚、黏膜與黏液、呼吸道的纖毛、胃酸、眼淚與唾液中能分解細菌細胞壁的<strong>溶菌酶</strong>（1922 年由弗萊明發現）。皮膚與腸道中的<strong>正常菌群</strong>也佔據了空間與養分，讓病原菌難以立足（" + LS(20) + u"）。"),
   ("h", u"先天免疫與適應性免疫"),
   ("ul", [u"<strong>先天免疫</strong>：快速、非專一。<strong>吞噬細胞</strong>（嗜中性球、巨噬細胞）辨識微生物共同的特徵（例如細菌的細胞壁成分），把它們吞噬消化；發炎反應讓血管擴張、白血球聚集。", u"<strong>適應性免疫</strong>：較慢、高度專一，而且有<strong>記憶</strong>。B 細胞產生針對特定抗原的<strong>抗體</strong>；T 細胞殺死被感染的細胞、協調免疫反應。第二次遇到同一種病原時，記憶細胞能迅速而強烈地反應（見" + X("immunology-vaccines", u"免疫學與疫苗") + u"）。"]),
   ("h", u"疫苗：讓免疫系統先練習"),
   ("p", u"<strong>疫苗</strong>的原理是：讓免疫系統在不生病的情況下接觸病原的「樣本」，建立記憶。"),
   ("ul", [u"<strong>1796 年</strong>：英國醫師<strong>金納</strong>觀察到擠牛奶的女工得過輕微的牛痘後就不會得天花，於是把牛痘接種到一個男孩身上，證明他對天花有了免疫力。「vaccine」一詞來自拉丁文的「牛」。", u"<strong>1880 年代</strong>：巴斯德發展減毒的雞霍亂、炭疽與狂犬病疫苗（" + LS(1) + u"）。"]),
   ("t", [u"疫苗類型", u"例子"], [[u"減毒活疫苗", u"麻疹、腮腺炎、德國麻疹（MMR）、口服小兒麻痺"], [u"不活化疫苗", u"注射式小兒麻痺、A 型肝炎、多數流感疫苗"], [u"次單位／類毒素", u"B 型肝炎（" + LS(12) + u"）、破傷風、白喉、肺炎鏈球菌（莢膜多醣）"], [u"mRNA", u"新冠肺炎（2023 年諾貝爾醫學獎：卡里科與魏斯曼）"], [u"病毒載體", u"部分新冠肺炎疫苗、伊波拉疫苗"]]),
   ("h", u"消滅與控制疾病"),
   ("p", u"<strong>天花</strong>曾在 20 世紀殺死約三億人。經過全球的疫苗接種與「圍堵接種」策略，最後一個自然感染的病例出現在 1977 年的索馬利亞，世界衛生組織在 <strong>1980 年</strong>宣布天花根除——人類第一次消滅一種疾病。<strong>小兒麻痺</strong>也已接近根除，野生株只剩極少數國家仍有傳播。疫苗是公共衛生史上最具成本效益的介入措施之一；當接種率下降，麻疹等疾病就會捲土重來（群體免疫，見" + X("differential-equations", u"微分方程") + u"的 SIR 模型）。"),
  ],
  u"人體物理化學屏障有完整皮膚、黏膜黏液、呼吸道纖毛、胃酸、眼淚唾液中 1922 年弗萊明發現的溶菌酶，正常菌群佔據空間養分；先天免疫快速非專一吞噬細胞辨識共同特徵發炎反應，適應性免疫較慢高度專一有記憶 B 細胞產抗體 T 細胞殺感染細胞，二次遇到迅速強烈反應；疫苗讓免疫系統不生病接觸樣本建立記憶，1796 年金納觀察擠奶女工得牛痘不得天花接種男孩證明免疫，vaccine 源於拉丁文牛，1880 年代巴斯德減毒雞霍亂炭疽狂犬病疫苗；減毒活疫苗 MMR 口服小兒麻痺、不活化疫苗注射小兒麻痺 A 肝流感、次單位類毒素 B 肝破傷風白喉肺炎鏈球菌、mRNA 新冠 2023 年諾貝爾獎卡里科與魏斯曼、病毒載體；天花 20 世紀殺約三億人，最後自然感染 1977 年索馬利亞，1980 年 WHO 宣布根除為首個被消滅疾病，小兒麻痺接近根除，接種率下降麻疹捲土重來。",
  [u"先天免疫與適應性免疫有什麼不同？", u"金納的牛痘接種是如何發現的？", u"天花是如何被根除的？"]),

lesson(u"重要的病原菌", u"認識敵人",
  [u"認識常見的細菌性疾病", u"理解細菌致病的機制", u"了解結核病等重大傳染病"],
  [("h", u"細菌如何致病"),
   ("ul", [u"<strong>黏附與入侵</strong>：用線毛等黏附在宿主細胞上（" + LS(2) + u"），有些能侵入細胞內躲避免疫。", u"<strong>躲避免疫</strong>：莢膜防止被吞噬；有些能在吞噬細胞內存活（例如結核桿菌）。", u"<strong>外毒素</strong>：細菌分泌的蛋白質毒素，通常極毒且作用專一。<strong>肉毒桿菌毒素</strong>是已知最毒的物質之一，阻斷神經傳遞肌肉麻痺——稀釋到極低的劑量，就是醫美的「肉毒桿菌素」。破傷風毒素則造成肌肉持續收縮。", u"<strong>內毒素</strong>：革蘭氏陰性菌外膜上的脂多醣，大量釋放時引起發燒、血壓下降甚至<strong>敗血性休克</strong>。"]),
   ("h", u"重要的細菌性疾病"),
   ("t", [u"疾病", u"病原", u"傳播與特點"], [[u"結核病", u"結核分枝桿菌", u"飛沫與空氣；生長極慢（倍增時間約一天），治療需六個月以上"], [u"霍亂", u"霍亂弧菌", u"受污染的水；毒素造成大量水瀉，口服補液鹽能救命"], [u"傷寒", u"傷寒沙門氏菌", u"受污染的食物與水"], [u"肺炎", u"肺炎鏈球菌等", u"老人與幼兒的重要死因；有疫苗"], [u"鼠疫", u"鼠疫桿菌", u"跳蚤叮咬；14 世紀的黑死病殺死歐洲約三分之一的人口"], [u"胃潰瘍、胃癌", u"幽門螺旋桿菌", u"約一半的人類帶菌（" + LS(13) + u"）"], [u"出血性腸炎", u"腸道出血性大腸桿菌 O157:H7", u"未熟的牛絞肉、生菜；可能造成溶血性尿毒症候群"]]),
   ("h", u"結核病：古老而頑強"),
   ("p", u"<strong>結核病</strong>在埃及木乃伊中就已發現，19 世紀被稱為「白色瘟疫」，歐洲約四分之一的死亡由它造成。今天全世界約四分之一的人口可能帶有潛伏的結核菌，每年仍有一千萬人發病、超過一百萬人死亡，是單一病原造成死亡最多的傳染病之一（新冠肺炎大流行期間除外）。結核菌的細胞壁富含蠟質的分枝菌酸，使它耐乾燥、難以被藥物穿透，治療需要多種藥物合併使用數個月——病人如果中途停藥，就容易產生<strong>多重抗藥性結核</strong>（" + LS(18) + u"）。台灣推行「都治計畫」（DOTS），由關懷員親自看著病人服藥，大幅提高了完治率。"),
   ("h", u"不只是細菌"),
   ("p", u"疾病的發生是<strong>病原、宿主、環境</strong>三者互動的結果：同樣接觸結核菌，營養不良、愛滋病、糖尿病的人較容易發病；擁擠、通風不良的環境增加傳播（見" + X("disease-mechanisms", u"疾病機轉") + u"）。改善衛生、營養與居住條件，常常比藥物更早、更大幅地降低了傳染病的死亡率。"),
  ],
  u"細菌致病靠黏附入侵、躲避免疫（莢膜、在吞噬細胞內存活如結核桿菌）、外毒素蛋白質極毒專一（肉毒桿菌毒素最毒之一阻斷神經傳遞極低劑量為醫美肉毒桿菌素、破傷風毒素肌肉持續收縮）、內毒素革蘭氏陰性菌脂多醣引起發燒血壓下降敗血性休克；結核病飛沫空氣傳播倍增約一天治療六個月以上、霍亂受污染水大量水瀉口服補液鹽救命、傷寒、肺炎鏈球菌有疫苗、鼠疫跳蚤 14 世紀黑死病殺歐洲約三分之一人口、幽門螺旋桿菌約一半人類帶菌、O157:H7 未熟牛絞肉溶血性尿毒症；結核病見於埃及木乃伊 19 世紀稱白色瘟疫，全世界約四分之一人口潛伏感染每年一千萬發病超過一百萬死亡，分枝菌酸蠟質細胞壁耐乾燥難穿透，多藥合併數月中途停藥產生多重抗藥結核，台灣都治計畫 DOTS 關懷員看著服藥；疾病是病原宿主環境互動，改善衛生營養居住常比藥物更早降低死亡。",
  [u"外毒素與內毒素有什麼不同？", u"為什麼結核病的治療需要那麼久？", u"為什麼說疾病是病原、宿主與環境共同作用的結果？"]),

lesson(u"消毒與滅菌", u"殺死微生物的科學",
  [u"區分滅菌、消毒與防腐", u"理解 D 值與 z 值", u"了解常用的物理與化學方法"],
  [("h", u"名詞"),
   ("ul", [u"<strong>滅菌</strong>：殺死或去除<strong>所有</strong>的微生物，包括最頑強的細菌內孢子（" + LS(2) + u"）。", u"<strong>消毒</strong>：殺死大部分的病原微生物，但不一定能殺死孢子。用於物體表面。", u"<strong>防腐</strong>（抗菌）：用於皮膚等活組織的消毒，例如手術前的皮膚準備。", u"<strong>殺菌</strong>：食品中常指巴斯德殺菌等方法，降低微生物數量到安全的程度。"]),
   ("h", u"死亡是對數的"),
   ("p", u"微生物在致死條件下不是同時死亡，而是在每一段固定的時間內死掉<strong>固定的比例</strong>——存活數呈指數下降（" + LS(7) + u"的反面）。<strong>D 值</strong>是在特定溫度下，讓存活數減少 90%（一個對數）所需的時間。"),
   STERIL,
   ("ul", [u"<strong>z 值</strong>：使 D 值縮短為十分之一所需升高的溫度。許多細菌孢子的 z 值約 10 °C。", u"<strong>無菌保證水準</strong>（SAL）：醫療器材的滅菌通常要求 10<sup>−6</sup>，也就是每一百萬件中，最多只能有一件可能殘留活的微生物——因為死亡是機率性的，「絕對無菌」在數學上無法保證。"]),
   ("h", u"物理方法"),
   ("t", [u"方法", u"條件", u"用途"], [[u"高壓蒸氣滅菌", u"121 °C、約 15 分鐘以上（約兩大氣壓）", u"醫療器材、培養基、實驗廢棄物"], [u"乾熱", u"160～180 °C、1～2 小時", u"玻璃器皿、金屬（乾熱的殺菌效果比濕熱差）"], [u"巴斯德殺菌", u"63 °C、30 分鐘，或 72 °C、15 秒", u"鮮乳、果汁（不殺死孢子，需冷藏）"], [u"超高溫瞬間殺菌（UHT）", u"約 135～150 °C、數秒", u"保久乳（室溫可保存數月）"], [u"過濾", u"0.2 微米濾膜", u"不耐熱的液體（某些藥品、培養基添加物）"], [u"輻射", u"γ 射線、電子束", u"拋棄式針筒、手套、部分香料"], [u"紫外線", u"254 nm", u"表面與空氣（穿透力差）"]]),
   ("p", u"為什麼濕熱比乾熱有效？水蒸氣凝結時釋放大量的熱，而且水分讓蛋白質更容易變性。"),
   ("h", u"化學方法"),
   ("ul", [u"<strong>酒精</strong>：<strong>70%～75%</strong> 最有效——適量的水幫助穿透細胞與蛋白質變性，純酒精反而讓表面的蛋白質快速凝固形成保護層。酒精<strong>不能殺死孢子</strong>，對無套膜的<strong>諾羅病毒</strong>效果也差（" + LS(6) + u"）。", u"<strong>漂白水</strong>（次氯酸鈉）：便宜、廣效，稀釋後用於環境消毒。不能和酸性清潔劑混合（會產生氯氣）。", u"<strong>碘與優碘</strong>：手術部位的皮膚消毒。", u"<strong>過氧化氫</strong>、<strong>環氧乙烷</strong>（不耐熱的醫療器材）、<strong>戊二醛</strong>（內視鏡）。"]),
   ("h", u"最頑強的對手"),
   ("p", u"依照抵抗力由高到低：<strong>普利昂</strong>（造成狂牛症的錯誤摺疊蛋白質，一般的滅菌條件無法完全破壞）&gt; 細菌內孢子 &gt; 分枝桿菌 &gt; 無套膜病毒 &gt; 一般細菌 &gt; 有套膜病毒。"),
  ],
  u"滅菌殺死或去除所有微生物含內孢子、消毒殺死大部分病原不一定殺孢子用於物體表面、防腐用於皮膚等活組織、殺菌如巴斯德殺菌降低到安全程度；微生物在致死條件下每段時間死掉固定比例存活數指數下降，D 值為減少 90% 所需時間，z 值為使 D 值縮短為十分之一需升高的溫度孢子約 10 °C，無菌保證水準 SAL 10^−6 絕對無菌無法保證；高壓蒸氣 121 °C 約 15 分鐘以上約兩大氣壓、乾熱 160～180 °C 1～2 小時、巴斯德 63 °C 30 分鐘或 72 °C 15 秒需冷藏、UHT 約 135～150 °C 數秒保久乳、0.2 微米過濾、γ 射線電子束拋棄式針筒、紫外線 254 nm 穿透差，濕熱比乾熱有效因凝結放熱且水分助蛋白質變性；酒精 70%～75% 最有效純酒精使表面蛋白凝固，不殺孢子對諾羅病毒差，漂白水不可與酸性清潔劑混合產生氯氣，優碘、過氧化氫、環氧乙烷、戊二醛；抵抗力普利昂 > 內孢子 > 分枝桿菌 > 無套膜病毒 > 一般細菌 > 有套膜病毒。",
  [u"滅菌和消毒有什麼不同？", u"什麼是 D 值？如果某菌在 121 °C 的 D 值是 0.2 分鐘，要減少 12 個對數需要多久？", u"為什麼 70% 的酒精比 95% 的酒精消毒效果好？"]),

lesson(u"抗生素的發現", u"20 世紀最偉大的醫學革命",
  [u"了解抗生素的發現史", u"認識抗生素的作用機制", u"理解廣效與窄效抗生素"],
  [("h", u"魔法子彈"),
   ("p", u"20 世紀初，德國的<strong>埃爾利希</strong>夢想找到一顆「<strong>魔法子彈</strong>」：只攻擊病原、不傷害病人的化學物質。1909 年，他的團隊在測試了數百種含砷化合物之後，找到了能治療梅毒的<strong>灑爾佛散</strong>（606 號化合物）。1935 年，德國的<strong>多馬克</strong>發現了磺胺類藥物百浪多息（1939 年諾貝爾獎）——第一類廣泛使用的合成抗菌藥。"),
   ("h", u"弗萊明的培養皿"),
   ("p", u"1928 年 9 月，倫敦聖瑪麗醫院的<strong>弗萊明</strong>度假回來，發現一個培養葡萄球菌的培養皿被一團青黴菌污染了，而黴菌周圍的細菌都溶解了。他推論黴菌分泌了一種殺菌物質，命名為<strong>盤尼西林</strong>。但他無法大量純化這個不穩定的物質，研究停滯了十年。"),
   ("p", u"1939 年起，牛津大學的<strong>弗洛里</strong>與<strong>錢恩</strong>帶領團隊重新研究，成功純化盤尼西林並在 1941 年用於病人。第二次世界大戰期間，美國以大規模的深槽發酵（加上在一顆發霉的哈密瓜上找到的高產量菌株）量產盤尼西林，拯救了無數傷兵的生命。三人共獲 1945 年諾貝爾醫學獎（見" + X("nobel-medicine", u"諾貝爾醫學獎") + u"）。"),
   ("h", u"從土壤中尋寶"),
   ("p", u"美國的<strong>瓦克斯曼</strong>有系統地篩選土壤中的<strong>放線菌</strong>，他的研究生<strong>沙茨</strong>在 1943 年發現了<strong>鏈黴素</strong>——第一個能有效治療結核病的藥物。瓦克斯曼獲得 1952 年諾貝爾獎（沙茨的貢獻後來引起了爭議）。1940～60 年代是抗生素發現的「黃金時代」，今天使用的抗生素大部分類別都在這個時期被發現，其中許多來自土壤中的放線菌。"),
   ("h", u"作用機制"),
   ("t", [u"標的", u"抗生素類別", u"例子"], [[u"細胞壁合成", u"β-內醯胺類、醣肽類", u"盤尼西林、頭孢菌素、萬古黴素"], [u"蛋白質合成（核糖體）", u"胺基糖苷類、四環黴素、巨環內酯類", u"鏈黴素、四環黴素、紅黴素"], [u"DNA 複製", u"氟喹諾酮類", u"環丙沙星"], [u"葉酸合成", u"磺胺類", u"磺胺甲噁唑"], [u"細胞膜", u"多黏菌素", u"colistin"]]),
   ("p", u"這些標的都利用了細菌與人體細胞的差異（" + LS(2) + u"的選擇性毒性）。<strong>廣效</strong>抗生素對許多種細菌有效，<strong>窄效</strong>抗生素只對少數種類有效。廣效藥物方便，但也會殺死大量的正常菌群（" + LS(20) + u"），並對更多細菌造成抗藥性的篩選壓力。"),
   ("h", u"抗生素不能治感冒"),
   ("p", u"抗生素只對<strong>細菌</strong>有效，對<strong>病毒</strong>完全無效——病毒沒有細胞壁、沒有自己的核糖體（" + LS(6) + u"）。大多數的感冒、流感、急性支氣管炎是病毒引起的，吃抗生素不但沒有幫助，還會帶來副作用並促進抗藥性（" + LS(18) + u"）。"),
  ],
  u"20 世紀初埃爾利希夢想魔法子彈，1909 年測試數百種含砷化合物找到治梅毒的灑爾佛散 606 號，1935 年多馬克發現磺胺類百浪多息 1939 年諾貝爾獎；1928 年 9 月倫敦聖瑪麗醫院弗萊明度假回來發現青黴菌污染培養皿周圍細菌溶解，命名盤尼西林但無法純化停滯十年；1939 年起牛津弗洛里與錢恩純化盤尼西林 1941 年用於病人，二戰期間美國深槽發酵加發霉哈密瓜高產菌株量產救無數傷兵，1945 年三人諾貝爾醫學獎；瓦克斯曼篩選土壤放線菌，研究生沙茨 1943 年發現鏈黴素首個有效治結核藥，1952 年諾貝爾獎沙茨貢獻有爭議，1940～60 年代黃金時代多數抗生素類別來自放線菌；標的細胞壁 β-內醯胺醣肽、核糖體胺基糖苷四環黴素巨環內酯、DNA 氟喹諾酮、葉酸磺胺、細胞膜多黏菌素，皆利用選擇性毒性，廣效方便但殺正常菌群增加篩選壓力；抗生素對病毒無效，感冒流感急性支氣管炎多為病毒吃抗生素無益且促抗藥性。",
  [u"弗萊明發現盤尼西林之後，為什麼還要等十多年才能用於病人？", u"列出三種抗生素的作用標的。", u"為什麼抗生素不能治療感冒？"]),

lesson(u"抗藥性", u"一場演化的競賽",
  [u"理解抗藥性如何演化與擴散", u"認識抗藥性的機制與超級細菌", u"了解對抗抗藥性的策略"],
  [("h", u"弗萊明的警告"),
   ("p", u"1945 年，弗萊明在諾貝爾獎演講中就提出警告：如果使用的劑量不足，細菌會學會抵抗盤尼西林。他說對了。盤尼西林大量使用後不到十年，醫院中的金黃色葡萄球菌就有很大比例產生了抗藥性。此後每一種新抗生素上市，幾年到十幾年內就會出現抗藥菌。"),
   ("h", u"天擇的實驗"),
   ("p", u"抗生素並不會「教」細菌產生抗藥性。在一個龐大的細菌族群中，本來就可能有極少數因為隨機突變或從別的細菌得到基因（" + LS(10) + u"）而具有抗藥性。使用抗生素時，敏感的細菌被殺死，抗藥的細菌存活下來，而且少了競爭者——<strong>抗生素創造了篩選抗藥菌的環境</strong>。這是達爾文天擇最直接、最快速的例子。"),
   RESIST,
   ("h", u"抗藥的機制"),
   ("ul", [u"<strong>破壞藥物</strong>：β-內醯胺酶切開盤尼西林的四元環（見" + X("organic-chemistry", u"有機化學") + u"）。", u"<strong>改變標的</strong>：MRSA（抗甲氧西林金黃色葡萄球菌）改變了細胞壁合成酵素，讓 β-內醯胺類抓不住它。", u"<strong>把藥物抽出去</strong>：細胞膜上的<strong>外排幫浦</strong>。", u"<strong>減少進入</strong>：革蘭氏陰性菌改變外膜的孔道（" + LS(2) + u"）。"]),
   ("h", u"超級細菌"),
   ("p", u"對多種甚至幾乎所有抗生素都具抗藥性的細菌被稱為「<strong>超級細菌</strong>」：MRSA、抗萬古黴素腸球菌（VRE）、產生碳青黴烯酶的腸道菌（例如 2008 年首次報告的 NDM-1）、多重抗藥結核（" + LS(15) + u"）。2015 年，中國發現了能在細菌之間傳遞的多黏菌素抗藥基因 <strong>mcr-1</strong>——多黏菌素是「最後一道防線」，而這個基因被認為和養殖業大量使用多黏菌素有關。一項大型研究估計，2019 年全球約有 <strong>127 萬人</strong>直接死於抗藥性細菌感染；若不加以控制，到 2050 年每年可能有上千萬人死亡。"),
   ("h", u"對抗抗藥性"),
   ("ul", [u"<strong>合理使用</strong>：只在細菌感染時使用抗生素，選擇適當的藥物、劑量與療程，遵照醫師指示——不自行購買、不吃剩藥、不分享藥物。", u"<strong>感染控制</strong>：醫院的手部衛生、隔離措施（" + LS(13) + u"的塞麥爾維斯教訓）；疫苗減少感染，也就減少抗生素的使用（" + LS(14) + u"）。", u"<strong>減少畜牧業使用</strong>：許多國家已禁止把抗生素當作生長促進劑。", u"<strong>新藥與新療法</strong>：新抗生素的研發利潤低、難度高，近幾十年新類別極少；替代方法包括噬菌體療法（" + LS(6) + u"）、抗體、以 AI 篩選新抗生素（見" + X("ai-drug-discovery", u"AI 藥物發現") + u"）。", u"<strong>同一健康</strong>：人、動物、環境中的抗藥性互相關聯，需要跨領域的合作（" + LS(25) + u"）。"]),
  ],
  u"1945 年弗萊明諾貝爾演講警告劑量不足會使細菌學會抵抗，盤尼西林大量使用不到十年醫院金黃色葡萄球菌很大比例抗藥，每種新抗生素幾年到十幾年內出現抗藥菌；抗生素不教細菌抗藥，族群中本有極少數因突變或水平轉移抗藥，用藥殺敏感菌使抗藥菌存活且少競爭者，抗生素創造篩選環境為天擇最快例子；機制有破壞藥物 β-內醯胺酶、改變標的 MRSA、外排幫浦、減少進入外膜孔道；超級細菌有 MRSA、VRE、碳青黴烯酶腸道菌如 2008 年 NDM-1、多重抗藥結核，2015 年中國發現可傳遞的多黏菌素抗藥基因 mcr-1 與養殖業使用有關，2019 年全球約 127 萬人直接死於抗藥菌感染，2050 年每年可能上千萬；對策為合理使用不自行購買不吃剩藥、感染控制手部衛生與疫苗、減少畜牧使用禁止生長促進劑、新藥噬菌體抗體 AI 篩選、同一健康跨領域合作。",
  [u"抗生素是如何「篩選」出抗藥菌的？", u"列出兩種細菌抵抗抗生素的機制。", u"一般民眾可以如何幫助減緩抗藥性的問題？"]),

lesson(u"病毒感染與抗病毒藥物", u"在細胞裡作戰",
  [u"了解重要的病毒性疾病", u"理解抗病毒藥物的困難與策略", u"認識病毒的突變與演化"],
  [("h", u"重要的病毒性疾病"),
   ("t", [u"疾病", u"病毒", u"特點"], [[u"流感", u"流感病毒（RNA）", u"每年流行；抗原漂移需年年更新疫苗；1918 年大流行約數千萬人死亡"], [u"新冠肺炎", u"SARS-CoV-2", u"2019 年底出現，造成全球大流行"], [u"愛滋病", u"人類免疫缺乏病毒（HIV，反轉錄病毒）", u"攻擊 CD4 T 細胞；雞尾酒療法讓它成為可控制的慢性病"], [u"B 型與 C 型肝炎", u"HBV、HCV", u"慢性感染可導致肝硬化與肝癌；C 肝已可用口服藥治癒"], [u"子宮頸癌", u"人類乳突病毒（HPV）", u"有疫苗可以預防"], [u"登革熱", u"登革病毒", u"埃及斑蚊、白線斑蚊傳播；台灣南部夏秋季流行"], [u"腸病毒", u"腸病毒 71 型等", u"台灣幼兒的重要傳染病；重症可能致命"]]),
   ("h", u"為什麼抗病毒藥物難做"),
   ("p", u"病毒利用宿主細胞的機器複製（" + LS(6) + u"），能下手的「病毒特有」標的比細菌少得多，要殺病毒又不傷細胞很困難。而且不同的病毒差異極大，通常一種藥只對一種或一類病毒有效——沒有「廣效抗病毒藥」可以像廣效抗生素那樣使用。"),
   ("h", u"抗病毒藥物的策略"),
   ("ul", [u"<strong>阻止進入</strong>：例如阻斷 HIV 和輔助受體結合。", u"<strong>抑制基因體複製</strong>：核苷酸類似物——假的「積木」被病毒的聚合酶誤用，讓複製中斷。例如治療疱疹的阿昔洛韋、治療 B 肝與 HIV 的藥物、C 肝的索非布韋。", u"<strong>抑制蛋白酶</strong>：許多病毒先合成一條長的蛋白質，再由病毒自己的蛋白酶切成可用的片段。HIV 與新冠肺炎的口服藥都有蛋白酶抑制劑。", u"<strong>阻止釋出</strong>：流感藥物克流感（oseltamivir）抑制神經胺酸酶，讓新病毒無法離開細胞。"]),
   ("p", u"愛滋病的治療是一個成功的故事：1990 年代中期，何大一等人推動合併多種藥物的「<strong>雞尾酒療法</strong>」，讓病毒很難同時對所有藥物產生抗藥性。今天，規則服藥的感染者能把病毒量壓到測不到，壽命接近一般人，而且「<strong>測不到＝不具傳染力</strong>」（U=U）。"),
   ("h", u"RNA 病毒的快速演化"),
   ("p", u"RNA 病毒的聚合酶<strong>沒有校對功能</strong>，突變率比 DNA 病毒與細菌高得多。加上一個被感染的人體內可能有數十億個病毒顆粒，新的變異株不斷出現：流感的抗原漂移、新冠病毒的 Alpha、Delta、Omicron 等變異株。當兩種不同的流感病毒同時感染一個宿主（例如豬），基因片段可能重新組合（抗原移型），產生全新的病毒，可能引起<strong>大流行</strong>（" + LS(25) + u"）。"),
   ("h", u"病毒成為工具"),
   ("p", u"科學家也把病毒改造成治療的工具：用無害的病毒當作載體，把正常的基因送進病人的細胞（<strong>基因治療</strong>）；<strong>溶瘤病毒</strong>選擇性地感染並殺死癌細胞；噬菌體療法對抗抗藥菌（" + LS(18) + u"）。"),
  ],
  u"流感每年流行抗原漂移需年年更新疫苗 1918 年大流行數千萬死、新冠 2019 年底出現全球大流行、HIV 反轉錄病毒攻擊 CD4 T 細胞雞尾酒療法成慢性病、B C 肝慢性感染致肝硬化肝癌 C 肝可口服藥治癒、HPV 子宮頸癌有疫苗、登革熱埃及斑蚊白線斑蚊台灣南部夏秋流行、腸病毒 71 型台灣幼兒重要傳染病；病毒用宿主機器複製特有標的少，不同病毒差異大無廣效抗病毒藥；策略有阻止進入、核苷酸類似物抑制複製如阿昔洛韋與索非布韋、蛋白酶抑制劑 HIV 與新冠口服藥、克流感抑制神經胺酸酶阻止釋出；1990 年代中期何大一等推動雞尾酒療法，規則服藥病毒量測不到壽命接近一般人，U=U 測不到等於不具傳染力；RNA 病毒聚合酶無校對突變率高，新變異株如 Alpha Delta Omicron，兩種流感同時感染豬等宿主基因片段重組抗原移型可能大流行；病毒改造為基因治療載體、溶瘤病毒、噬菌體療法。",
  [u"為什麼抗病毒藥物比抗生素難開發？", u"愛滋病的雞尾酒療法為什麼有效？", u"為什麼 RNA 病毒容易產生新的變異株？"]),
]),

(u"模組 E｜微生物與人類", [

lesson(u"人體微生物群", u"你不是一個人",
  [u"認識人體微生物群的組成與分布", u"了解微生物群對健康的影響", u"了解益生菌與糞便移植"],
  [("h", u"數十兆個室友"),
   ("p", u"人體內外住著數十兆個微生物，主要在<strong>大腸</strong>中。過去常說「細菌細胞是人體細胞的十倍」，但 2016 年的研究重新估計：一個成人約有 38 兆個細菌、30 兆個人體細胞，兩者大約<strong>一比一</strong>。不過，微生物群的基因總數遠多於人類的約兩萬個基因。腸道中的細菌有數百到上千種，總重約 0.2 公斤。這整個群落叫做<strong>微生物群</strong>（microbiota），它們的基因總和叫做<strong>微生物體</strong>（microbiome）。"),
   ("h", u"微生物群做什麼"),
   ("ul", [u"<strong>消化</strong>：分解人體無法消化的膳食纖維，產生<strong>短鏈脂肪酸</strong>，是大腸細胞的主要能量來源，也有抗發炎的作用（見" + X("nutrition", u"營養學") + u"）。", u"<strong>維生素</strong>：合成維生素 K 與部分 B 群。", u"<strong>保護</strong>：佔據空間與養分，排擠病原菌（定殖抗性）。", u"<strong>訓練免疫系統</strong>：無菌動物的免疫系統發育不全。", u"<strong>腸腦軸</strong>：腸道微生物可能透過神經、激素與免疫訊號影響大腦與行為——這是熱門但仍在發展中的研究領域（見" + X("neuroscience", u"神經科學") + u"）。"]),
   ("h", u"從出生開始"),
   ("p", u"嬰兒在出生時（特別是自然產）獲得第一批微生物，之後隨著哺乳、飲食與環境逐漸發展，大約三歲時接近成人的組成。母乳中的寡糖不能被嬰兒消化，卻是某些<strong>比菲德氏菌</strong>的專屬食物——母親在「餵」寶寶的腸道菌。"),
   ("h", u"失衡與疾病"),
   ("p", u"微生物群的失衡與許多疾病有關：發炎性腸道疾病、肥胖、第二型糖尿病、過敏、甚至某些神經精神疾病。但要注意：很多研究只發現了<strong>相關性</strong>，不一定是<strong>因果關係</strong>——是失衡造成疾病，還是疾病造成失衡？「<strong>衛生假說</strong>」則認為，現代生活過於乾淨、減少接觸微生物，可能讓免疫系統失調，增加過敏與自體免疫疾病。"),
   ("h", u"抗生素與困難梭菌"),
   ("p", u"廣效抗生素（" + LS(17) + u"）會殺死大量的正常腸道菌。這時，原本被壓制的<strong>困難梭菌</strong>可能大量繁殖，造成嚴重甚至致命的腸炎，而且容易一再復發。最有效的治療之一出乎意料：<strong>糞便微生物移植</strong>——把健康捐贈者的糞便菌群移植到病人腸道中，治癒率可達八、九成。"),
   ("h", u"益生菌與益生質"),
   ("p", u"<strong>益生菌</strong>是攝取足量時對健康有益的活微生物（例如某些乳酸菌、比菲德氏菌）；<strong>益生質</strong>是能被有益菌利用的食物成分（例如膳食纖維、寡糖）。益生菌對某些情況（例如抗生素相關的腹瀉）有一定的證據，但效果因菌株而異，市面上許多產品的宣稱缺乏嚴謹的證據。均衡、多樣、富含纖維的飲食，可能是養好腸道菌最可靠的方法。"),
  ],
  u"人體內外數十兆微生物主要在大腸，2016 年重新估計成人約 38 兆細菌 30 兆人體細胞約一比一，微生物群基因遠多於人類約兩萬基因，腸道數百到上千種總重約 0.2 公斤，群落為 microbiota 基因總和為 microbiome；功能有分解膳食纖維產生短鏈脂肪酸供大腸細胞能量抗發炎、合成維生素 K 與 B 群、定殖抗性排擠病原、訓練免疫無菌動物免疫發育不全、腸腦軸仍在發展；嬰兒出生時特別自然產獲第一批微生物約三歲接近成人，母乳寡糖是比菲德氏菌專屬食物；失衡與發炎性腸道疾病肥胖糖尿病過敏有關但多為相關非因果，衛生假說；廣效抗生素殺正常菌使困難梭菌繁殖嚴重腸炎易復發，糞便微生物移植治癒率八九成；益生菌為足量有益活微生物、益生質為有益菌可利用的成分，益生菌對抗生素相關腹瀉有證據但因菌株而異，均衡多樣高纖飲食最可靠。",
  [u"人體中的細菌細胞和人體細胞數量大約是什麼比例？", u"腸道微生物群有哪些功能？", u"為什麼糞便微生物移植能治療困難梭菌感染？"]),

lesson(u"食品微生物：發酵與腐敗", u"同一群微生物的兩張臉",
  [u"了解發酵食品的微生物學", u"理解食品腐敗的原因", u"認識傳統的食品保存方法"],
  [("h", u"發酵：人類最古老的生物技術"),
   ("p", u"早在知道微生物存在之前，人類就已經利用它們製作食物數千年了。發酵讓食物更耐保存、更有風味、更容易消化（見" + X("fermentation", u"發酵") + u"）。"),
   ("t", [u"食品", u"主要微生物", u"作用"], [[u"優格", u"保加利亞乳桿菌、嗜熱鏈球菌", u"乳糖 → 乳酸，酸使牛奶蛋白質凝固"], [u"起司", u"乳酸菌、凝乳酶；部分加入黴菌", u"凝乳、熟成產生風味"], [u"麵包", u"酵母", u"CO₂ 讓麵團膨脹"], [u"啤酒、葡萄酒、米酒", u"酵母", u"糖 → 酒精 ＋ CO₂"], [u"醬油、味噌", u"米麴菌、乳酸菌、酵母", u"分解大豆蛋白產生胺基酸（鮮味）"], [u"泡菜、酸菜、韓式泡菜", u"乳酸菌", u"酸化，抑制腐敗菌"], [u"醋", u"醋酸菌", u"酒精 → 醋酸"], [u"納豆", u"納豆菌（枯草桿菌）", u"產生黏絲與維生素 K₂"], [u"紅麴", u"紅麴菌", u"色素與風味"]]),
   ("h", u"微生物的競爭"),
   ("p", u"發酵的關鍵是讓「好菌」勝過「壞菌」：乳酸菌產生的酸降低 pH，酵母產生的酒精，以及鹽分、低氧環境，都讓腐敗菌與病原菌難以生存。這是一種「以菌治菌」的保存方法。製作泡菜時加鹽、壓緊排出空氣，正是為乳酸菌創造優勢。"),
   ("h", u"腐敗"),
   ("p", u"同樣的微生物活動，如果不是我們想要的，就叫做<strong>腐敗</strong>：牛奶變酸結塊、肉類發出臭味（蛋白質分解產生胺類與硫化物）、水果發霉、麵包長黴。腐敗菌通常不一定會致病，但會讓食物失去價值；反過來，致病菌常常<strong>不會</strong>讓食物的外觀或氣味改變——「聞起來沒壞」不代表安全（" + LS(22) + u"）。"),
   ("h", u"保存食物的原理"),
   ("t", [u"方法", u"原理"], [[u"冷藏、冷凍", u"低溫減慢或停止生長（" + LS(7) + u"）；冷凍不會殺死大多數的細菌"], [u"加熱（殺菌、罐頭）", u"殺死微生物（" + LS(16) + u"）"], [u"乾燥、糖漬、鹽漬", u"降低水活性"], [u"醃漬、發酵", u"降低 pH"], [u"真空、充氮包裝", u"排除氧氣（但要注意厭氧的肉毒桿菌）"], [u"防腐劑", u"抑制微生物（例如己二烯酸、苯甲酸，依法規限量使用）"]]),
   ("p", u"多種方法常常組合使用，每一種都只「一點點」不利於微生物，合起來就能有效保存，同時保留食物的品質——這叫做<strong>柵欄技術</strong>。"),
   ("p", u"延伸：" + X("cooking-science", u"烹飪科學") + u"。"),
  ],
  u"人類在知道微生物前數千年就利用其製作食物，發酵使食物耐保存有風味易消化；優格保加利亞乳桿菌與嗜熱鏈球菌乳糖成乳酸凝固、起司乳酸菌凝乳酶黴菌熟成、麵包酵母 CO2、啤酒葡萄酒米酒酵母糖成酒精、醬油味噌米麴菌分解大豆蛋白產生鮮味、泡菜酸菜乳酸菌酸化、醋酸菌酒精成醋酸、納豆菌黏絲維生素 K2、紅麴菌；發酵關鍵是好菌勝壞菌，乳酸降 pH、酒精、鹽分、低氧，製泡菜加鹽壓緊排氣；腐敗為不想要的微生物活動，牛奶變酸肉發臭水果發霉，腐敗菌不一定致病，致病菌常不改變外觀氣味聞起來沒壞不代表安全；保存原理冷藏冷凍減慢（冷凍不殺菌）、加熱殺菌罐頭、乾燥糖漬鹽漬降水活性、醃漬發酵降 pH、真空充氮排氧（注意肉毒桿菌）、防腐劑己二烯酸苯甲酸限量，多法組合為柵欄技術。",
  [u"舉三種發酵食品，並說明參與的微生物。", u"為什麼「聞起來沒壞」不代表食物安全？", u"什麼是柵欄技術？"]),

lesson(u"食物中毒與食品安全", u"從廚房到餐桌",
  [u"認識常見的食物中毒病原", u"了解食物中毒的預防原則", u"認識台灣重大的食物中毒事件"],
  [("h", u"感染型與毒素型"),
   ("ul", [u"<strong>感染型</strong>：吃下活的病原菌，在腸道中繁殖致病，通常有一段潛伏期（數小時到數天）。例如沙門氏菌、腸炎弧菌、彎曲桿菌、諾羅病毒。", u"<strong>毒素型</strong>：細菌在食物中繁殖時產生毒素，吃下的是毒素。發病快（可能數十分鐘到數小時），而且某些毒素<strong>耐熱</strong>——重新加熱食物可以殺死細菌，卻破壞不了已經產生的毒素。例如金黃色葡萄球菌、仙人掌桿菌、肉毒桿菌。"]),
   ("h", u"常見的病原"),
   ("t", [u"病原", u"常見來源", u"特點"], [[u"腸炎弧菌", u"生食或未煮熟的海鮮；砧板交叉污染", u"嗜鹽，過去是台灣最常見的食物中毒菌之一"], [u"沙門氏菌", u"蛋、禽肉", u"生蛋製品（如自製美乃滋、提拉米蘇）要小心"], [u"金黃色葡萄球菌", u"人的手部傷口、鼻腔", u"毒素耐熱；便當、飯糰"], [u"仙人掌桿菌", u"米飯、澱粉類", u"「炒飯症候群」：煮好的飯在室溫久放"], [u"諾羅病毒", u"生蠔、受污染的食物與水；人傳人", u"極易傳染，酒精效果差（" + LS(16) + u"）"], [u"李斯特菌", u"即食肉品、軟質起司、生乳", u"能在冰箱中生長（" + LS(7) + u"）；對孕婦特別危險"], [u"肉毒桿菌", u"自製罐頭、真空包裝食品、蜂蜜", u"厭氧；毒素造成神經麻痺；一歲以下嬰兒不宜吃蜂蜜"]]),
   ("h", u"台灣的教訓"),
   ("ul", [u"<strong>真空包裝豆干</strong>：2010 年前後，曾有真空包裝的豆干在常溫販售，導致肉毒桿菌中毒。此後規定真空包裝的即食豆類製品必須冷藏，或經過足以殺死孢子的商業滅菌（" + LS(16) + u"）。", u"<strong>2024 年寶林茶室事件</strong>：台北一家餐廳的粿條（米製品）在製作或保存過程中，被一種細菌（唐菖蒲伯克氏菌椰毒病原型）污染並產生<strong>米酵菌酸</strong>，造成多人中毒、數人死亡。米酵菌酸耐熱、沒有解毒劑，過去主要見於東南亞與中國的發酵米製品與椰子製品，在台灣是首見。事件凸顯了米製品與澱粉類食品在溫暖環境中保存的風險。"]),
   ("h", u"預防的五個要點"),
   ("ol", [u"<strong>清潔</strong>：洗手、清洗食材與器具。", u"<strong>生熟分開</strong>：生肉、海鮮與即食食品使用不同的砧板與刀具，避免交叉污染。", u"<strong>徹底煮熟</strong>：特別是肉類、海鮮、蛋（中心溫度達 75 °C 以上）。", u"<strong>注意溫度</strong>：熱食保持 60 °C 以上、冷食 7 °C 以下；熟食不要在室溫放超過約兩小時（" + LS(7) + u"）。", u"<strong>安全的水與原料</strong>。"]),
   ("p", u"這也是世界衛生組織「食品安全五要點」的核心。食物中毒的檢驗與溯源，需要微生物學與分析化學的合作（見" + X("analytical-chemistry", u"分析化學") + u"的食品安全）。"),
  ],
  u"感染型吃下活病原菌在腸道繁殖有潛伏期如沙門氏菌腸炎弧菌彎曲桿菌諾羅病毒，毒素型吃下毒素發病快部分毒素耐熱重新加熱殺菌但破壞不了毒素如金黃色葡萄球菌仙人掌桿菌肉毒桿菌；腸炎弧菌生食海鮮砧板交叉污染嗜鹽過去為台灣最常見之一、沙門氏菌蛋禽肉生蛋製品、金黃色葡萄球菌手部傷口鼻腔毒素耐熱便當飯糰、仙人掌桿菌米飯室溫久放炒飯症候群、諾羅病毒生蠔人傳人酒精效果差、李斯特菌即食肉品軟質起司生乳冰箱中生長孕婦危險、肉毒桿菌自製罐頭真空包裝蜂蜜一歲以下不宜吃；2010 年前後常溫真空包裝豆干肉毒桿菌中毒後規定冷藏或商業滅菌，2024 年台北寶林茶室粿條被唐菖蒲伯克氏菌椰毒病原型污染產生米酵菌酸多人中毒數人死亡耐熱無解毒劑台灣首見；預防五要點清潔、生熟分開、徹底煮熟中心 75 °C 以上、熱 60 °C 以上冷 7 °C 以下室溫不超過約兩小時、安全的水與原料，為 WHO 食品安全五要點核心。",
  [u"感染型與毒素型食物中毒有什麼不同？", u"為什麼有些食物中毒無法靠重新加熱來預防？", u"列出預防食物中毒的五個要點。"]),

lesson(u"環境微生物與物質循環", u"地球的清潔隊",
  [u"了解微生物在碳、氮循環中的角色", u"認識污水處理的微生物學", u"了解生物復育與塑膠分解"],
  [("h", u"分解者"),
   ("p", u"如果沒有微生物，死去的動植物會永遠堆積，養分無法回到土壤。<strong>細菌與真菌</strong>是地球最主要的<strong>分解者</strong>，把有機物分解成 CO₂、水與礦物質，讓元素重新被植物利用（" + LS(4) + u"）。一公克肥沃的土壤中可能有數十億個細菌、數千種不同的物種。"),
   ("h", u"碳循環"),
   ("p", u"微生物同時<strong>固定</strong>碳（海洋浮游植物的光合作用，" + LS(5) + u"）與<strong>釋放</strong>碳（分解、呼吸）。在無氧的環境——沼澤、稻田、垃圾掩埋場、反芻動物的胃——<strong>甲烷菌</strong>把有機物轉成<strong>甲烷</strong>（" + LS(3) + u"），它的溫室效應比 CO₂ 強數十倍。北極永凍土融化時，被凍結數萬年的有機物開始被微生物分解，釋放大量的 CO₂ 與甲烷——這是氣候變遷的一個令人擔憂的正回饋（見" + X("climate-change", u"氣候變遷") + u"）。"),
   ("h", u"氮循環：幾乎全靠微生物"),
   ("ol", [u"<strong>固氮</strong>：N₂ → NH₃（根瘤菌、藍綠菌，" + LS(9) + u"）。", u"<strong>硝化</strong>：NH₃ → NO₂⁻ → NO₃⁻（硝化菌，化學自營）。植物主要吸收硝酸鹽。", u"<strong>脫氮</strong>：NO₃⁻ → N₂（脫氮菌，在無氧環境中），把氮還給大氣。"]),
   ("p", u"人類透過哈伯法製造的氮肥，已經讓地球上的「可利用氮」大幅增加。過多的氮流入河川與海洋，造成藻華與缺氧的「死亡區」（" + LS(5) + u"）。"),
   ("h", u"污水處理"),
   ("p", u"現代污水處理廠的核心是一群辛勤工作的微生物。1914 年，英國的阿登與洛克特發展出<strong>活性污泥法</strong>：在曝氣池中打入空氣，讓好氧微生物把污水中的有機物分解成 CO₂ 與新的菌體；微生物聚集成絮狀的「污泥」，在沉澱池中沉降分離，部分回流再利用。進階處理還利用硝化與脫氮菌去除氮，避免河川優養化。污泥再經過<strong>厭氧消化</strong>，產生的沼氣（甲烷）可以發電（見" + X("water-environment", u"水資源與環境") + u"、" + X("chemical-engineering", u"化學工程") + u"）。"),
   ("h", u"生物復育"),
   ("p", u"利用微生物分解環境中的污染物，叫做<strong>生物復育</strong>。2010 年墨西哥灣<strong>深水地平線</strong>鑽油平台漏油事件後，海洋中天然存在的「吃油細菌」大量繁殖，分解了相當比例的原油。對於被含氯溶劑污染的地下水（例如台灣的 RCA 案，見" + X("analytical-chemistry", u"分析化學") + u"），也可以注入營養鹽，促進能把污染物脫氯的厭氧菌。"),
   ("h", u"吃塑膠的細菌"),
   ("p", u"2016 年，日本科學家在一座寶特瓶回收廠附近的污泥中，發現了一種能分解 <strong>PET</strong> 塑膠的細菌（大阪堺市的 Ideonella sakaiensis），它演化出了能切斷 PET 酯鍵的酵素。科學家正在改造這些酵素，希望能在工業規模上把塑膠分解回原料（見" + X("organic-chemistry", u"有機化學") + u"的塑膠回收）——不過這仍然無法取代減少塑膠的使用。"),
  ],
  u"沒有微生物死去動植物永遠堆積，細菌真菌為最主要分解者把有機物分解成 CO2 水礦物質，一公克肥沃土壤數十億細菌數千種；微生物固定碳（浮游植物）與釋放碳（分解呼吸），無氧環境沼澤稻田掩埋場反芻胃甲烷菌產甲烷溫室效應強數十倍，北極永凍土融化微生物分解釋放 CO2 甲烷為正回饋；氮循環固氮 N2 成 NH3（根瘤菌藍綠菌）、硝化 NH3 成 NO2− 成 NO3−（硝化菌化學自營）、脫氮 NO3− 成 N2 還給大氣，哈伯法氮肥過多流入水體造成藻華死亡區；1914 年阿登與洛克特活性污泥法曝氣池好氧微生物分解有機物絮狀污泥沉降回流，進階硝化脫氮去氮，污泥厭氧消化產沼氣發電；生物復育 2010 年深水地平線漏油吃油細菌分解原油，含氯溶劑地下水注入營養鹽促進厭氧脫氯菌；2016 年日本在寶特瓶回收廠污泥發現分解 PET 的 Ideonella sakaiensis，改造酵素工業分解塑膠但無法取代減量。",
  [u"說明氮循環中固氮、硝化與脫氮的過程。", u"活性污泥法如何處理污水？", u"為什麼永凍土融化會加劇氣候變遷？"]),

lesson(u"工業與能源微生物", u"看不見的工廠",
  [u"了解工業發酵的發展", u"認識微生物生產的重要產品", u"了解微生物在能源上的應用"],
  [("h", u"從釀酒到工業發酵"),
   ("p", u"微生物的工業應用遠超出食品。第一次世界大戰期間，英國急需製造無煙火藥用的<strong>丙酮</strong>。化學家<strong>魏茨曼</strong>發展出用<strong>梭菌</strong>發酵玉米澱粉生產丙酮與丁醇的方法，大規模量產——這是最早的大型工業發酵之一。（魏茨曼後來成為以色列的第一任總統。）第二次世界大戰期間的盤尼西林量產（" + LS(17) + u"），則奠定了現代<strong>深槽發酵</strong>技術：在數萬公升的不鏽鋼發酵槽中，精確控制溫度、pH、溶氧與攪拌（見" + X("chemical-engineering", u"化學工程") + u"的反應器）。"),
   ("h", u"微生物生產的產品"),
   ("t", [u"產品", u"微生物", u"用途"], [[u"檸檬酸", u"黑麴菌", u"飲料的酸味劑、清潔劑；全球年產量約兩百萬公噸"], [u"麩胺酸鈉（味精）", u"麩胺酸棒狀桿菌", u"1956 年日本開發發酵法；鮮味調味料"], [u"胺基酸（離胺酸等）", u"細菌", u"飼料添加物"], [u"抗生素", u"放線菌、黴菌", u"醫藥"], [u"維生素 B₁₂", u"細菌", u"只有微生物能合成"], [u"酵素", u"細菌、真菌", u"洗衣粉、紡織、食品加工"], [u"黃原膠", u"野油菜黃單胞菌", u"食品增稠劑、醬料"], [u"基因工程藥物", u"大腸桿菌、酵母", u"胰島素、疫苗（" + LS(12) + u"）"]]),
   ("h", u"生質能源"),
   ("ul", [u"<strong>生質乙醇</strong>：酵母發酵甘蔗或玉米的糖。巴西大量使用甘蔗乙醇作為汽車燃料。爭議是「與人爭糧」——所以研究轉向用農業廢棄物（纖維素）生產「第二代」乙醇，難點在於分解堅硬的纖維素。", u"<strong>沼氣</strong>：厭氧消化畜牧糞尿、廚餘、污泥產生甲烷（" + LS(23) + u"）。台灣許多養豬場設有沼氣發電設施。", u"<strong>微藻</strong>：生長快、油脂含量高，被研究用於生產生質柴油，但成本仍高。", u"<strong>微生物燃料電池</strong>：讓細菌把代謝產生的電子直接傳給電極（" + LS(9) + u"）。"]),
   ("h", u"其他工業應用"),
   ("ul", [u"<strong>生物冶金</strong>：利用嗜酸的化學自營菌（" + LS(9) + u"）從低品位的礦石中溶出銅、金——全世界有相當比例的銅是用這種「生物浸出」方法生產的。", u"<strong>生物塑膠</strong>：某些細菌在體內累積聚羥基烷酸酯（PHA），是可生物分解的塑膠；聚乳酸（PLA）的原料乳酸也來自發酵（見" + X("organic-chemistry", u"有機化學") + u"）。", u"<strong>合成生物學</strong>：重新設計微生物，生產原本來自植物或石油的化學品——例如用工程酵母生產青蒿素的前驅物（" + LS(12) + u"）。"]),
  ],
  u"一戰英國急需製造無煙火藥用的丙酮，魏茨曼以梭菌發酵玉米澱粉生產丙酮丁醇大規模量產為最早大型工業發酵之一，魏茨曼後為以色列首任總統；二戰盤尼西林量產奠定深槽發酵，數萬公升不鏽鋼槽控溫 pH 溶氧攪拌；產品有黑麴菌檸檬酸年產約兩百萬公噸、麩胺酸棒狀桿菌味精 1956 年日本發酵法、離胺酸飼料、放線菌黴菌抗生素、只有微生物能合成的維生素 B12、洗衣粉紡織酵素、黃原膠增稠劑、大腸桿菌酵母基因工程藥物；生質乙醇酵母發酵甘蔗玉米巴西大量使用但與人爭糧，轉向纖維素第二代乙醇；沼氣厭氧消化糞尿廚餘污泥台灣養豬場發電；微藻生質柴油成本仍高；微生物燃料電池；生物冶金嗜酸化學自營菌從低品位礦石溶出銅金；細菌累積 PHA 生物塑膠與發酵乳酸製 PLA；合成生物學工程酵母生產青蒿素前驅物。",
  [u"魏茨曼的丙酮發酵為什麼重要？", u"列舉三種由微生物發酵生產的工業產品。", u"生質乙醇有什麼爭議？研究者如何嘗試解決？"]),

lesson(u"新興傳染病與同一健康", u"下一場大流行",
  [u"了解新興傳染病的來源與驅動因素", u"回顧近代重大的疫情", u"理解「同一健康」的觀念"],
  [("h", u"來自動物的疾病"),
   ("p", u"一項 2008 年的大型分析發現，1940～2004 年間出現的新興傳染病中，約 <strong>60%</strong> 是<strong>人畜共通傳染病</strong>（從動物傳給人），其中大部分來自<strong>野生動物</strong>。病毒原本在動物宿主中和平共存，當人類與動物的接觸增加，病毒有機會「跨物種傳播」（spillover）。"),
   ("t", [u"疾病", u"年代", u"可能的動物來源"], [[u"1918 年流感", u"1918～1919", u"鳥類（經過不明的中間宿主）；全球約數千萬人死亡"], [u"愛滋病", u"20 世紀初跨物種，1981 年被辨識", u"中非的黑猩猩"], [u"SARS", u"2002～2003", u"蝙蝠 → 果子狸；台灣 2003 年經歷嚴重的疫情與和平醫院封院"], [u"H1N1 新型流感", u"2009", u"豬（鳥、豬、人流感基因重組）"], [u"MERS", u"2012 起", u"蝙蝠 → 單峰駱駝"], [u"伊波拉", u"2014～2016 西非大流行", u"蝙蝠（推測）"], [u"新冠肺炎", u"2019 年底起", u"源頭仍有爭議；近緣病毒存在於蝙蝠"]]),
   ("h", u"驅動因素"),
   ("ul", [u"<strong>土地利用改變</strong>：砍伐森林、開發讓人類深入野生動物的棲地。", u"<strong>野生動物貿易</strong>與活體動物市場。", u"<strong>集約化畜牧</strong>：大量動物密集飼養，病毒容易傳播與突變（例如禽流感）。", u"<strong>全球化</strong>：搭飛機一天之內就能把病原帶到世界的另一端（見" + X("airports", u"機場") + u"）。", u"<strong>氣候變遷</strong>：蚊子的分布範圍擴大，登革熱等疾病往更高緯度與高海拔擴散（見" + X("climate-change", u"氣候變遷") + u"）。", u"<strong>抗藥性</strong>（" + LS(18) + u"）與疫苗接種率下降。"]),
   ("h", u"同一健康"),
   ("p", u"<strong>同一健康</strong>（One Health）的觀念認為：<strong>人類的健康、動物的健康與環境的健康是緊密相連的</strong>，必須由醫師、獸醫、生態學家、環境科學家共同合作。例子包括：監測野生鳥類與家禽的禽流感、管理畜牧業的抗生素使用、在可能爆發疫情的地區進行病毒的監測與基因定序。"),
   ("h", u"準備下一次"),
   ("p", u"新冠肺炎大流行讓世界付出了極大的代價，也帶來了重要的經驗：快速的病毒基因定序與資料分享（病毒序列在疫情初期幾天內就在網路上公開）、mRNA 疫苗以前所未有的速度研發（" + LS(14) + u"）、邊境管制與接觸者追蹤、口罩與通風、流行病學模型（見" + X("differential-equations", u"微分方程") + u"的 SIR 模型）。台灣在 SARS 之後建立了中央流行疫情指揮中心等防疫體系，在新冠疫情初期發揮了作用。科學家普遍認為，下一次大流行<strong>不是會不會發生，而是何時發生</strong>。"),
  ],
  u"2008 年大型分析 1940～2004 年新興傳染病約 60% 為人畜共通多來自野生動物，接觸增加使病毒跨物種傳播；1918 年流感鳥類數千萬人死、愛滋病 20 世紀初跨物種 1981 年辨識來自中非黑猩猩、SARS 2002～2003 蝙蝠到果子狸台灣 2003 年和平醫院封院、2009 年 H1N1 豬基因重組、MERS 2012 起蝙蝠到單峰駱駝、伊波拉 2014～2016 西非、新冠 2019 年底源頭仍有爭議近緣病毒在蝙蝠；驅動因素有砍伐森林深入棲地、野生動物貿易活體市場、集約化畜牧禽流感、全球化搭飛機一天到另一端、氣候變遷蚊子分布擴大登革熱往高緯高海拔、抗藥性與疫苗接種率下降；同一健康認為人類動物環境健康緊密相連需醫師獸醫生態環境科學家合作，如監測禽流感管理畜牧抗生素病毒監測定序；新冠經驗有快速定序資料分享、mRNA 疫苗快速研發、邊境管制接觸追蹤、口罩通風、SIR 模型，台灣 SARS 後建立中央流行疫情指揮中心，下一次大流行不是會不會而是何時。",
  [u"為什麼大部分的新興傳染病來自動物？", u"列出三個增加新興傳染病風險的因素。", u"什麼是「同一健康」？舉一個例子。"]),

lesson(u"總結", u"與微生物共存",
  [u"整理整門課的重點", u"建立對微生物的平衡觀點", u"了解延伸學習的方向"],
  [("h", u"整門課回顧"),
   ("t", [u"模組", u"核心"], [[u"微生物的世界", u"雷文霍克與巴斯德、細菌構造與革蘭氏染色、古菌與三域、真菌、原生生物與藻類、病毒"], [u"生長與代謝", u"指數成長與生長曲線、純培養與洋菜、代謝多樣性與大氧化事件"], [u"遺傳與生物技術", u"基因水平轉移、CRISPR、重組 DNA 與 PCR"], [u"微生物與疾病", u"柯霍法則、免疫與疫苗、病原菌、D 值與滅菌、抗生素、抗藥性、抗病毒"], [u"微生物與人類", u"微生物群、發酵與腐敗、食物中毒、物質循環、工業發酵、同一健康"]]),
   ("h", u"平衡的觀點"),
   ("p", u"微生物常被看作「病菌」，但絕大多數的微生物對人類無害，而且不可或缺：它們製造了我們呼吸的氧氣、循環了地球上的元素、分解了死去的生物、住在我們的腸道裡幫助消化與訓練免疫、為我們發酵食物、生產藥物。少數的病原微生物確實造成了巨大的苦難，但人類用科學——衛生、疫苗、抗生素——大幅降低了它們的威脅。今天的挑戰是如何<strong>聰明地</strong>與微生物共存：保護有益的、防範有害的、避免抗藥性。"),
   ("h", u"給日常生活的建議"),
   ("ul", [u"正確<strong>洗手</strong>：最簡單也最有效的防疫措施。", u"<strong>按時接種疫苗</strong>。", u"<strong>不濫用抗生素</strong>：感冒不需要抗生素；遵照醫囑完成療程。", u"<strong>食品安全</strong>：生熟分開、徹底煮熟、注意溫度。", u"<strong>多樣的飲食</strong>：善待你的腸道微生物。"]),
   ("h", u"延伸學習"),
   ("p", u"醫學微生物學、病毒學、免疫學、微生物生態學、食品微生物學、工業微生物學、合成生物學、流行病學。延伸：" + X("immunology-vaccines", u"免疫學與疫苗") + u"、" + X("fermentation", u"發酵") + u"、" + X("genetics-dna", u"遺傳與 DNA") + u"、" + X("pharmacology", u"藥理學") + u"、" + X("disease-mechanisms", u"疾病機轉") + u"。"),
  ],
  u"整門課涵蓋微生物的世界（雷文霍克巴斯德細菌構造革蘭氏染色古菌三域真菌原生生物藻類病毒）、生長代謝（指數成長生長曲線純培養洋菜代謝多樣性大氧化事件）、遺傳生物技術（基因水平轉移 CRISPR 重組 DNA PCR）、微生物與疾病（柯霍法則免疫疫苗病原菌 D 值滅菌抗生素抗藥性抗病毒）、微生物與人類（微生物群發酵腐敗食物中毒物質循環工業發酵同一健康）；絕大多數微生物無害且不可或缺，製造氧氣循環元素分解生物幫助消化訓練免疫發酵食物生產藥物，少數病原以衛生疫苗抗生素降低威脅，挑戰是聰明共存保護有益防範有害避免抗藥性；日常建議正確洗手、按時接種疫苗、不濫用抗生素、食品安全、多樣飲食；延伸醫學微生物病毒學免疫學微生物生態食品工業微生物合成生物學流行病學。",
  [u"為什麼說絕大多數的微生物對人類是有益的？", u"在日常生活中，你可以做哪些事來與微生物「聰明地共存」？", u"本課中你覺得最令人驚訝的微生物知識是什麼？"]),
]),
]
